import {DOC_NOVEMBER} from './docs-november.js';
import { WORKSTATION_RELEASE, WORKSTATION_DOCS } from './docs-workstation-tools.js';
// Product documentation is deliberately authored from the implemented workflows.
// Keep capability boundaries explicit; a settings page is not a live service.
import { DOC_WORKFLOWS } from './docs-workflows.js';
import { DOC_GOVERNANCE } from './docs-governance.js';
import { DOC_CONNECTIONS } from './docs-connections.js';
import { DOC_COLLABORATION } from './docs-collaboration.js';
import { DOC_TEMPLATES_AND_SCHEDULING } from './docs-playbooks.js';
import { API_PROVIDERS } from './ai-provider-catalog.js';
import { DOC_AI_CONNECTIONS } from './docs-ai-connections.js';
import { DOC_LOCAL } from './docs-local.js';
export const DOC_GROUPS = [
  { id: 'updates', title: 'What’s New', description: 'Release notes and changes to Frondose.' },
  { id: 'getting-started', title: 'Getting started', description: 'Your first workspace, a clear brief, and a useful result.' },
  { id: 'workspace', title: 'Your workspace', description: 'Find, organize, and return to the work that matters.' },
  { id: 'projects-routes', title: 'Projects & Routes', description: 'Turn direction into scoped, reviewable work.' },
  { id: 'chats-agents', title: 'Chats & agents', description: 'Conversations, deliberate execution, and workspace-aware collaborators.' },
  { id: 'workbench', title: 'Workbench', description: 'Explore a linked project, inspect changes, and run commands.' },
  { id: 'knowledge', title: 'Knowledge & review', description: 'Keep sources, decisions, and exact-version outputs connected.' },
  { id: 'integrations', title: 'Connections', description: 'Understand provider setup and what each service can actually do.' },
  { id: 'governance', title: 'People & access', description: 'Membership, custom roles, temporary access, and owner decisions.' },
  { id: 'settings', title: 'Settings & data', description: 'Shape the interface and manage workspace information responsibly.' },
  { id: 'workflows', title: 'Practical guides', description: 'End-to-end ways to plan, investigate, review, and improve.' },
  { id: 'developers', title: 'Developers', description: 'Architecture, execution boundaries, and safe contribution practices.' },
];

const section = (id, title, paragraphs, extra = {}) => ({ id, title, paragraphs, ...extra });
const article = (id, group, title, description, sections, extra = {}) => ({ id, group, title, description, sections, ...extra });

const REFERENCE_ARTICLES = [
  article('project-reviews-automations','updates','Projects, review notes & automations','A local project folder, inline review notes and deliberately scheduled CLI work.',[
    section('projects','Projects and worktrees stay distinct',['The sidebar Projects folder lists only the current workspace’s projects as simple name rows. Click a project to open its description and planning details; Quick access controls sorting. Worktrees have their own tool: each is another directory with its own checked-out branch and files, sharing the repository’s Git objects. They are not a sandbox and are not the same thing as a project.','Use Manage worktrees to create or open a reviewed sibling checkout. Opening another project/workspace preserves existing processes and protects drafts. Branch-specific file/planning tab layouts are optional and remain off by default; runtime tabs are retained.']),
    section('notes','Review beside the source',['Hover a rendered Markdown paragraph or select exact text to reveal its left-edge note control. The selected-text composer appears in a nonmodal margin rail; saved notes highlight their exact current source. Code-line notes appear directly below the line. Replies, reactions, explicit resolution and stale-anchor disclosure remain available. Unsaved replies stay mounted when CodeMirror virtualizes lines off-screen.','The paper-plane chooser opens an existing CLI tab after verifying its terminal ownership. It previews fresh bounded comment context and requires you to check that the CLI is idle with an empty prompt before inserting a draft. It never presses Enter, infers that silence means idle, or injects into a plain shell. A new-CLI chooser is also available. Provider-native working/idle telemetry is not universally supported.']),
    section('automations','Local automations with explicit consent',['Automations is a workspace tab with templates, search, status filters and run receipts. Save a task as a Route or choose an existing Route, review its exact prompt and directory, select Codex or Claude Code, and approve the schedule and possible provider charges. Hourly, daily, weekdays, weekly and one-time schedules run only while the local host and computer are awake. Native Windows first-task launches require a directly executable CLI, not an unsafe arbitrary-prompt batch shim.','Missed occurrences are skipped, not replayed as a burst. Active or uncertain work in the workspace prevents overlapping scheduled launches. Route or directory changes pause the old grant; re-review it to activate a revised schedule. A durable reserved receipt prevents automatic replay after an uncertain dispatch. A dispatched terminal is not falsely labelled an AI-completed task; open the CLI to inspect its result. Pausing stops future schedules, not existing sessions.']),
    section('desktop','A lighter desktop refresh',['What’s New articles now open in workspace tabs, while ordinary Docs and Settings remain standalone. After a real version change, only the matching installed release is offered, with replayable spotlight guidance. Help includes Check for updates. Actual install/download still requires a configured Frondose release feed and platform trust; this local ad-hoc Mac build does not pretend to provide a public signed updater.','Files, browser pages, localhost and supported web-app views have visible refresh controls with draft protection. The bottom desktop bar reports actual process memory/CPU and running terminals, without invented provider quotas or SSH state. The approved Mac flower icon keeps its original artwork with a smaller standard Dock footprint.']),
    section('activation','Local build boundaries',['New backend features need the updated local host. If an older external host still owns running terminals, Frondose leaves it alive and reports the activation requirement instead of stopping those sessions. macOS packaging and native smoke tests are separate from Windows/Linux policy tests and actual provider account acceptance.']),
  ]),

  article('local-cli-workspace', 'updates', 'Your local workspace', 'A CLI-first workspace with project planning, local files, terminal splits and browser sessions.', [
    section('workspace', 'Start in your directory, or open a terminal at home', ['Workspace opens a New tab chooser. Terminal opens directly. To open an installed agent without typing its command, use Settings → CLI Agents → Open AI Sessions → Terminal. Its working directory is the linked workspace folder, or the server-selected OS home when no folder is linked; home is not silently bound as a project. Markdown editing and the file explorer still require a linked directory. Browser tabs use isolated Chromium in Frondose desktop, with an editable address bar for websites and local HTTP servers; the ordinary website does not embed arbitrary pages in an iframe.', 'Today, Inbox, Workbench, Frondose personal agent, agent profiles, AI Connections and Conversations are retired from the local interface. Existing records and histories are retained; removing navigation does not erase the database.']),
    section('cli', 'Use the installed tool directly', ['Discovery adapts Orca’s licensed command metadata and bounded filesystem installation lookup. It checks PATH and conventional install/version-manager directories without executing shell startup files, installing packages, logging in or sending prompts. A detected CLI is not proof of account access or model entitlement.', 'Explicit CLI launch runs as this computer’s OS user. The CLI manages its own supported login and tools. Native commands are not confined to a Frondose sandbox. Cloud AI still sends context to its provider; local Frondose does not mean cloud models work offline.']),
    section('tabs', 'Tabs with a lighter touch', ['Short inset separators and rounded hover surfaces keep tabs distinct. Selected tabs slide, new tabs enter, and popup exits retain only bounded inert pictures—not a duplicated terminal, editor or browser. Keyboard actions remain immediate; reduced motion removes travel. Right-click supports persistent names, safe refresh and vertical tabs. Combine up to eight views, preview docking by dragging, and resize dividing borders. Phone-width screens provide a focused-view switcher instead of tiny multi-column tools.', 'AI CLI chats are not replaced by ordinary navigation. Settings and Docs stay outside the tab strip. Tab preferences control compact or comfortable sizing and close-button visibility. Terminal preferences configure the bound project or the separate workspace home host, and reject saving against a changed directory binding.']),
    section('history', 'Find supported native sessions and reusable commands', ['Session history search is optional. Explicit Refresh index reads supported Codex and Claude Code JSONL histories locally; searching other directories needs a separate All local sessions opt-in. Bounded title and user/assistant text indexing excludes tools, reasoning, website chats and archived Codex sessions. Exact resume validates the source, provider identity and original linked directory before opening the real CLI. Other providers keep their own native history commands.', 'Quick Commands saves searchable text without executing it. Insert adds a single line without Enter; Run executes in a shell and Send submits to an AI CLI, potentially consuming provider usage. Terminal scrollback and Scroll to latest remain available; full-screen tools can manage alternate-screen scrolling themselves.']),
    section('github', 'Use GitHub deliberately', ['The optional header detects the linked directory’s existing GitHub remote. Connection checks the installed GitHub CLI account; detection alone does not log in or publish anything. The repository dialog shows local branches and dirty status, explicit read-only Issues search and PR refresh, and a Projects on GitHub link rather than an in-app Projects integration.', 'Branch changes refuse active work or dirty disk state, guard editor drafts and refresh Files and clean previews. Frondose does not automatically initialize Git, invent a remote, stash, reset, fetch, commit or push. A missing GitHub CLI or failed account read gets an actionable source state and Retry.']),
    section('notices', 'Welcome notifications and What’s New', ['Onboarding’s fourth step automatically requests a welcome system notification. You may continue without allowing it. Native pending, system-accepted and failed states are reported separately from permission; system acceptance does not guarantee a visible banner, which OS settings or Focus can suppress. Dismissible tips retain their exit motion and respect reduced motion.', 'Product release notes are called What’s New and open in a centered reader with Go to Docs. Read receipts avoid repeated announcements in the same local identity and workspace. An actual changed packaged app version can show matching authored notes or a clear message when exact notes are absent; first installation and development builds do not fabricate an update. A real update download/install scheduler remains separate work.']),
    section('close', 'Close a view or stop its work', ['Closing a working terminal asks before ending anything. Close tab only keeps its process running; Reopen last closed tab can restore the view during this workspace session. Stop & close is available only for freshly verified sessions owned by that view, and it waits for confirmed exit. Unknown or legacy ownership does not expose a stop-all shortcut.', 'AI CLI chats are protected from ordinary navigation replacement. Right-click a tab to rename, refresh its view without restarting its CLI, show vertical tabs, or combine up to eight resizable views. Unsaved files keep Save changes, Discard and Cancel. Native resume uses each CLI’s own session history; it does not import ordinary provider website chats.']),
    section('limits', 'What remains separate', ['The desktop browser and PTY are real native features, but this is selective Orca reuse—not the entire application, daemon, Design Mode or add-on system. Mac native smoke tests and cross-platform fixture tests do not certify a Windows or Linux installation. Phone access, signed distribution and process survival across server restart remain separate work.']),
  ], { related: ['local-frondose'], appLink: { view: 'workspace', label: 'Open workspace' } }),
  article('your-agents-library', 'updates', 'Your Agents, connected', 'A searchable home for provider connections and personalized agents, with setup choices matched to each provider.', [
    section('library', 'Find your next connection', ['Your Agents now starts with your existing connected identities. Search Agent Connections to find a provider, explore the three featured connections, or browse the grouped catalog. Featured cards are editorial selections, not measured popularity rankings. Saved profiles and genuinely connected accounts remain distinct; a catalog entry is not proof that an account is ready to run.', 'Provider details show product illustrations, an overview and the connection routes implemented for that provider. The illustrations are examples, not live messages, account data or screenshots of your workspace.']),
    section('identities', 'Connect a provider or personalize an agent', ['Choose Connect for a direct provider identity, or Create agent connection for a separately named, personalized agent when that route is available. Supported choices may include an API key, provider-supported browser authorization, or a computer running the provider’s CLI. Unsupported authorization choices are not presented as working integrations.', 'A direct-provider mention prepares that provider’s conversation; it does not replace another conversation’s responding agent or launch work by itself. Personalized agents keep their own identities and Frondose-owned conversation histories. Existing native CLI chats are not imported or synchronized.']),
    section('focus', 'Keep your place while exploring', ['The sidebar is narrower, and selected tabs move between options with a sliding highlight. Dialog motion follows the control you opened. Keyboard navigation remains immediate, and reduced-motion preferences remove spatial movement.', 'What’s new opens here in a centered reader without navigating away from your draft. Closing a displayed update marks it read for this browser, account and workspace. Go to Docs deliberately opens the full handbook. Contact us remains in the Help menu as a placeholder: it does not send or upload a message.']),
    section('boundaries', 'Connection setup is still explicit', ['Opening the catalog, reading a guide or choosing a provider never starts a paid AI run. Account access, credentials, model availability and computer consent are checked through the existing connection flow. Provider-specific setup and live-account verification are separate from these interface changes. Continue to review the exact context and requested tool access before sending work.']),
  ], { related: ['provider-connections', 'agent-profiles', 'navigation'], appLink: { view: 'agents', label: 'Explore Your Agents' } }),
  article('conversation-interface', 'chats-agents', 'Conversations and Active work', 'Read replies, open real results, and follow execution without turning the conversation into a terminal.', [
    section('messages', 'A readable conversation', ['Your messages appear on the right in fit-content neutral bubbles; agent replies appear on the left. Replies support nested lists, tables, inline code, fenced code, quotes, task lists and mathematical notation rendered locally. Reactions, replies, bookmarks and attachments remain available.', 'Links show a provider mark, direct-origin favicon or globe fallback. Frondose never executes raw HTML from a reply, automatically loads Markdown images, or treats quoted code as an applied change.']),
    section('results', 'Documents and observed changes', ['Document and handbook links open a temporary full-size Docs reader. Back returns to the source conversation; the reader is not a permanent navigation tab. Fresh server access is checked when a workspace document or current output version is opened.', 'Code-change cards appear only for saved server-observed run comparisons. Concurrent edits may be included: these are not proof of authorship. View changes opens Workbench. Restoration uses the separate reviewed checkpoint flow; no blanket undo is implied. Workspace-action receipts distinguish a pending proposal from an applied change.']),
    section('activity', 'Keep execution details in Active work', ['A working conversation shows compact status and Open Active work. That separate page contains recorded public progress, tools, commands and other observed events. Private model reasoning is not exposed as a transcript.', 'You can keep writing notes or talk to another connected agent. A follow-up for the busy agent is saved as a queued next-turn instruction, not injected into the current provider session. Review its draft and send it explicitly. Protected cross-conversation handoffs preserve source permissions and do not start another paid run automatically.']),
  ], { appLink: { view: 'chats', label: 'Open Conversations' }, related: ['personal-agent-setup'] }),
  article('personal-agent-setup', 'chats-agents', 'Choose Frondose’s AI connection', 'Set the personal agent’s identity and explicitly choose the account it uses.', [
    section('binding', 'Choose, then save', ['Open Frondose → Setup, choose a verified AI connection, and save. Connected accounts are never selected automatically. A legacy saved Codex default is not explicit consent; choose and save once. If the selected account disconnects, Frondose asks for reconnection and never silently substitutes a different identity.', 'Setup controls Frondose’s name, picture, purpose, guidelines and context preferences. A picture can be dropped into the image field and cropped. These preferences do not grant provider or workspace permissions. Ordinary agent profiles keep their independent selected accounts.']),
    section('places', 'One place to talk', ['Frondose’s own tab contains Setup, Activity and Scheduled. Open conversation returns to existing work; New conversation explicitly creates a draft. Opening a tab never starts AI work. All chat takes place in Conversations, including entry points from agent profiles and mentions.', 'Clearing the selected connection keeps history, profiles and schedule definitions. Existing personal-agent live launches and scheduled dispatch still require a matching explicit connection. Saved history remains readable under its source permissions.']),
  ], { appLink:{view:'rumbo-agent',label:'Open Frondose setup'},related:['conversation-interface'] }),
  article('initial-launch', 'updates', 'Initial Launch', 'The first Frondose release notes: a new name, connected agents, and a simpler place to work.', [
    section('identity', 'Introducing Frondose', ['Frondose replaces Talvori, formerly Rumbo. The indigo F mark appears throughout the app and its install icons. Existing workspace content, conversations, preferences and provider credentials remain in place; legacy links and exports stay compatible.']),
    section('workspace', 'Work with connected agents', ['Projects, Routes and Areas organize work and the agents associated with it. Conversations use connected agent profiles rather than a second provider/model selector. Sending captures the exact current context; file access and elevated tools still require explicit authorization.', 'Enable automatic low-risk actions in Settings → Agent awareness to let connected agents create safe new Routes and link themselves to accessible work. The current signed-in user’s permissions still apply. Deletion, archiving, overwriting existing content, permissions, external effects and paid launches are not authorized by this switch.']),
    section('scheduling', 'Ask for work at a time', ['Conversations can prepare scheduled work. A proposed schedule is not a running task: review its exact prompt, model, time and context, then confirm it. Scheduled work records its outcome in Activity and uses current access at execution time. The server must be running; missed or uncertain work is not blindly replayed.']),
    section('availability', 'Release scope', ['These notes describe the current Frondose build, not a claim that public hosting, every provider login, or every external integration is ready. API/OAuth routes require each user’s own account access. Public mode remains an invite-only beta; provider app registrations and live-account verification must be completed before those sign-in methods are advertised as verified. Non-AI Plugins remain Coming soon.']),
  ], { related: ['provider-connections', 'chat-basics', 'navigation'] }),
  article('start-guide', 'getting-started', 'Start with one outcome', 'A practical first pass through Frondose, from a brief to a reviewed result.', [
    section('overview', 'A connected place for work', ['Frondose connects projects, Routes, conversations, agents, and the outputs you review. A project gives work a home. A Route describes a specific outcome. A chat holds discussion, while a session records an explicitly launched execution. You can plan and write notes before connecting a provider or linking a folder.']),
    section('first-work', 'Create a small, complete workflow', [], { steps: ['Create a project with a short purpose and a definition of success.', 'Add a Route with a concrete deliverable and an acceptance checklist.', 'Start a chat to clarify the brief. Choose whether you are saving a note or sending to a selected agent.', 'If execution is needed, check the provider and access mode before sending.', 'Save the useful result as an output in Library, review its exact version, and then update the Route.'] }),
    section('next', 'Keep the first outcome small', ['A good first Route is “Draft a comparison of two options” or “Fix this one reproducible layout bug.” Put necessary sources beside it and make the review criteria observable. Finishing a run is not the same as accepting its result; keep those decisions separate.'], { note: 'Opening a page, preparing a session, or creating a project never starts an agent.' }),
  ], { related: ['projects', 'route-agreements', 'chat-basics', 'outputs'], appLink: { view: 'projects', label: 'Open projects' }, image: 'projects' }),

  article('workspace-basics', 'getting-started', 'How Frondose fits together', 'Understand the objects you work with before adding more structure.', [
    section('structure', 'Choose the right home', ['Frondose is a solo-first AI work environment. Areas organize durable domains such as Product, Engineering, Research or Personal administration; they do not require a human team. Projects collect briefs, milestones, Routes, documents, chats and memory. The intended lifecycle is Intent → Route → Run → Output → Review → Memory. A Route remains the connected unit of work.']),
    section('conversation-execution', 'Separate discussion from execution', ['Chats are continuing conversations. Sessions record agent runs, including their progress and outcome. Agent profiles describe a collaborator’s purpose and instructions; provider connections supply the actual execution capability. Creating a profile does not connect an account or prove that its provider is ready.']),
    section('evidence', 'Keep evidence connected', ['Library outputs are versioned deliverables. Knowledge entries record facts, decisions, preferences, and instructions. Context snapshots freeze reviewed text for later use. These objects answer different questions: what was produced, what should be remembered, and what information was supplied.'], { bullets: ['Use a document for a living brief.', 'Use a Route for accountable work.', 'Use an output for something that needs review.', 'Use a context snapshot when the exact source text matters.'] }),
  ], { related: ['teams', 'projects', 'agent-profiles', 'context-snapshots'] }),

  article('planning-without-provider', 'getting-started', 'Plan before connecting an agent', 'Use Frondose for project structure and notes without launching AI work.', [
    section('available', 'Start with the information you have', ['Projects, Routes, documents, saved views, Area resources, and notes are useful without a provider connection. You can write a brief, collect source links, agree on success criteria, and record a decision before deciding which agent should do the work. A project also does not need a linked folder just to organize planning.']),
    section('prepare', 'Prepare a brief', [], { steps: ['Describe the intended result in a project or Route.', 'Record constraints, required evidence, and things outside the scope.', 'Add relevant documents or approved knowledge.', 'Create a conversation for questions and save notes there.', 'Connect a provider only when you are ready to deliberately send a message or launch a session.'] }),
    section('check', 'Check the mode when you move to execution', ['General chat uses supplied context and does not require project files. Project reading or coding requires a chosen working folder and the appropriate execution mode. Do not put credentials in a brief as a substitute for connection setup. A planned integration or a saved profile is not a live connection.']),
  ], { related: ['chat-basics', 'chat-access', 'provider-connections'], appLink: { view: 'documents', label: 'Open documents' } }),

  article('navigation', 'workspace', 'Navigate your workspace', 'Use the sidebar, commands, favorites, and workspace-local history.', [
    section('sidebar', 'One place to return to work', ['The Focused sidebar shows 11 core destinations: Today, Frondose, Starred, Inbox, Runs, Agents, Areas, Projects, Routes, Conversations, and AI connections. Other pages are in More, Search, or Sidebar customization; hiding a tab does not delete its data. Existing saved hide and order choices remain in effect. Area children open scoped work directly, and Saved views has its own page rather than a nested sidebar folder.']),
    section('commands', 'Find a destination quickly', ['Open Search and commands with Command/Ctrl K. It is useful when a page is hidden from the sidebar or when you know an item’s name but not where it belongs. In Appearance & navigation you can choose header quick-access shortcuts. Pinned tabs and starred objects are navigation shortcuts, not copies of work: show them in the header or switch to a draggable dock that turns vertical near the screen edges.']),
    section('history', 'Go back without leaving Frondose', ['Use the app’s back and forward controls or Command/Ctrl [ and Command/Ctrl ]. This history stays within the current workspace and resets on reload or workspace changes. It is separate from your browser’s own history.'], { note: 'Hiding an item changes your navigation, not its permissions or archive state. Use sidebar customization to bring it back.' }),
  ], { related: ['sidebar-customization', 'search', 'saved-views', 'keyboard-shortcuts'] }),

  article('home-focus', 'workspace', 'Home and Focus', 'Separate a useful attention queue from the entire inventory of work.', [
    section('home', 'Start with what changed', ['Home gathers work needing attention, active work, ready work, followed projects, recent places, and activity. Use it to answer “What should I look at now?” rather than treating it as a second project database. The check-in change count describes changes since your visit; it is not a notification-delivery service.']),
    section('focus', 'Focus is a view, not another task list', ['Focus derives a queue from existing workspace work. Update the original Route or project rather than creating a duplicate just to make it visible. Project grouping can help you switch context less often. Snooze an item when it is not relevant now and bring it back when you are ready to inspect it.']),
    section('habit', 'Build a short review habit', [], { steps: ['Scan attention items and inspect failures before retrying anything.', 'Pick a small amount of ready work with clear next steps.', 'Review the project context before launching a session.', 'Return accepted results to their Routes and projects.'], note: 'Home presentation and attention preferences are personal to this browser and workspace. They do not assign work to another user.' }),
  ], { related: ['routes', 'session-progress', 'preferences'], appLink: { view: 'overview', label: 'Open Home' } }),

  article('search', 'workspace', 'Search and filter', 'Find workspace content with type, project, and status filters.', [
    section('global', 'Search across the workspace', ['Search and commands can find workspace objects and matching message text. Results include useful excerpts and links back to the item, including message deep links. Use a distinctive phrase or title first, then narrow the query when several kinds of work share the same words.']),
    section('filters', 'Make the query specific', ['Workspace search understands type:, project:, and status: filters. Combine a text phrase with the relevant filter to reduce noise. A page’s own search field instead searches the collection shown there, such as integrations, documents, or Library entries.'], { bullets: ['Use type: to narrow the kind of object.', 'Use project: when a phrase occurs across multiple projects.', 'Use status: when you are looking for work in a particular lifecycle state.', 'Clear filters if an expected item is missing before assuming it was deleted.'] }),
    section('saved', 'Keep a useful Route query', ['For a recurring Route search, create a saved view with a title query, stage, projects, or assigned agents. It remains a live query against the original Routes. Search results and saved views do not grant access to project folders or trigger agent work.']),
  ], { related: ['saved-views', 'navigation'], appLink: { view: 'views', label: 'Open saved views' } }),

  article('saved-views', 'workspace', 'Saved views', 'Keep a live Route query instead of maintaining a second list.', [
    section('purpose', 'A named way to look at work', ['Saved views store filter criteria, not duplicated Routes. A view can match a title phrase, a lifecycle stage, projects, and assigned agents. When a matching Route changes, its appearance in the view changes too. This makes views useful for “Ready for review,” work for one agent, or a particular project area.']),
    section('create', 'Create and use a view', [], { steps: ['Open Saved views from the sidebar.', 'Create a new view and give it a name that explains its purpose.', 'Set the title, stage, project, and agent filters you need.', 'Save the view and inspect its matching Routes.', 'Open a result to change the original Route.'] }),
    section('maintain', 'Keep views understandable', ['Prefer a few clear questions over many nearly identical views. If a view looks empty, review the criteria and the status of its parent projects. Favoriting a view makes it easier to revisit. Hiding it from navigation does not remove its saved criteria or change the Routes it matches.']),
  ], { related: ['search', 'routes', 'sidebar-customization'], appLink: { view: 'views', label: 'Open saved views' } }),

  article('teams', 'workspace', 'Areas and their spaces', 'Organize domains of personal work, context and agent preparation.', [
    section('overview', 'Give a domain of work a home', ['An Area gathers projects, Routes, Updates, Resources and Documents around a durable purpose. Product, Engineering, Research and Personal administration are examples, not required departments. Existing Teams become Areas without deleting their resources, history, access grants or relationships. A project remains the better unit for a time-bounded outcome.']),
    section('organize', 'Set up an Area', [], { steps: ['Create an Area with a clear name and purpose.', 'Associate relevant projects and Routes.', 'Collect useful links and files in Resources and keep longer guidance in Documents.', 'Save Area instructions, default agents and Context Packs in Area settings.', 'Enable Contacts only if a directory helps your work.'] }),
    section('people', 'Defaults are not authorization', ['Area instructions, selected agents, Context Packs and read-tool preferences are saved preparation choices. They do not automatically enter current runs or grant tool access. The permission policy remains review-only.', 'Contacts are optional directory entries. Hiding Contacts does not delete existing people records. Adding a name, email or role does not authenticate anyone or grant workspace access.']),
  ], { related: ['team-resources', 'team-settings', 'documents', 'service-boundaries'], appLink: { view: 'teams', label: 'Open Areas' }, image: 'teams' }),

  article('team-resources', 'workspace', 'Area Resources', 'Keep files, websites, GitHub branches, and Frondose references together.', [
    section('types', 'Choose a resource that fits', ['Area Resources accepts files, images, audio and video, safe website links, GitHub branch links, and references to Frondose objects. Resources appear in the Area overview and in a dedicated Resources tab. A link is a reference to another place; adding it does not import all of that site’s contents into agent context.']),
    section('add', 'Add and organize resources', [], { steps: ['Open an Area’s Resources tab.', 'Choose the resource type and provide a clear name.', 'Upload a file or enter its URL or Frondose reference.', 'Use search to find it later, and edit the description when its purpose changes.', 'Archive outdated resources; restore them if they become useful again.'] }),
    section('limits', 'Files and removal', ['Uploads are limited to 25 MB per file and 250 MB per workspace. Permanent removal requires an archived resource and explicit confirmation. Website icons are loaded from the linked site’s origin with a fallback; availability depends on that site.'], { note: 'Workspace JSON exports do not include uploaded resource files. Download important files individually before relying on an export as a backup.' }),
  ], { related: ['teams', 'import-export', 'context-snapshots'], appLink: { view: 'teams', label: 'Open Areas' } }),

  article('projects', 'projects-routes', 'Projects', 'Give an outcome direction, boundaries, and a place for its work.', [
    section('brief', 'Write the direction before the task list', ['A project holds a brief, goal, direction, scope, success criteria, and exclusions. These fields reduce repeated explanations across Routes and chats. State what the outcome is for and what would make it unsuccessful, not just a list of activities you expect to perform.']),
    section('structure', 'Connect the work', ['Projects can have an Area, lead, dates, milestones, Routes, documents, chats, activity, and memory. Use milestones for meaningful checkpoints and Routes for individual deliverables. A project picture can help recognition; uploading or dropping a PNG, JPEG, or WebP opens the crop and positioning step.']),
    section('review', 'Keep the project current', [], { steps: ['Record risks or open questions with an owner.', 'Review milestones and acceptance criteria when scope changes.', 'Update dates only when they reflect an actual plan.', 'Keep the brief current as decisions settle.', 'Record a retrospective when the outcome is complete.'], note: 'Linking a folder is optional for planning. Reading project files or running commands requires an explicitly chosen environment.' }),
  ], { related: ['milestones-timeline', 'routes', 'workbench-overview'], appLink: { view: 'projects', label: 'Open projects' }, image: 'projects' }),

  article('milestones-timeline', 'projects-routes', 'Milestones, health, and timelines', 'Understand progress without mistaking a date map for a forecast.', [
    section('milestones', 'Make checkpoints testable', ['A milestone should describe a recognizable achievement rather than a vague activity. Add acceptance criteria so “ready” means the same thing during planning and review. Project risks and questions provide context for health; keep owners and explanations current instead of relying only on a colored state.']),
    section('timeline', 'Read actual dates', ['The project timeline uses project dates, Route due dates, and milestone targets. Undated work remains visible separately rather than receiving invented durations. An unfinished prerequisite with a later due date than its dependent Route is highlighted as a potential planning conflict.']),
    section('route-progress', 'Compare milestones with leaf progress', ['Project Route progress counts active leaf Routes rather than counting parents again alongside their children. A leaf is a Route without children; a parent does not become a leaf merely because its children are archived. Done leaves count toward completion, while cancelled and archived leaves are excluded and reported separately. This describes the workflow records, not the amount of effort or independently verified outcome.', 'A filtered list may show a child without its parent when the parent does not match the filter. That does not detach the relationship. Restricted, missing, cyclic, or otherwise invalid ancestry prevents a trustworthy complete percentage; inspect the hierarchy warning instead of treating a partial view as complete. Milestone completion and project health remain separate explicit decisions.']),
    section('use', 'Use the map to ask better questions', [], { bullets: ['Does the prerequisite finish before the dependent work needs it?', 'Is an important milestone missing acceptance criteria?', 'Which work is still undated because the scope is uncertain?', 'Does the project’s stated health have an explanation?'], note: 'The timeline is not a scheduling engine or completion prediction. Moving a date does not change dependencies, start an agent, or guarantee capacity.' }),
  ], { related: ['projects', 'route-agreements', 'coordination'], appLink: { view: 'projects', label: 'Open projects' } }),

  article('routes', 'projects-routes', 'Routes: from brief to done', 'Describe one outcome and move it through a meaningful lifecycle.', [
    section('brief', 'Keep each Route reviewable', ['A Route is a unit of work with a title, brief, lifecycle stage, priority, and optional project or agent assignment. Write the intended output and constraints so the next person or agent can understand what success looks like. A title such as “Improve onboarding” needs a more concrete brief before execution.']),
    section('lifecycle', 'Use stages consistently', ['The Route lifecycle supports Backlog, Ready, In progress, Review, Blocked, Done, and Cancelled. Custom workflow names retain these underlying meanings. Ready means the brief can be acted on; Review means the result still needs judgment. A session completing does not automatically mean that the Route’s acceptance conditions have been met.']),
    section('hierarchy', 'Give a larger outcome smaller, reviewable parts', ['A sub-route is an ordinary Route with a parent. It keeps its own brief, stage, priority, agreement, updates, and reviewed outputs; it is not a checklist line or a separate kind of issue. Use the parent to describe the combined outcome and each child to describe an independently understandable part. Do not repeat the whole parent brief in every child when a clear link and a focused explanation are enough.', 'For example, a parent called “Make a connection ready to use” could contain Routes for registering the provider application, testing scoped imports, and writing the setup guide. Those Routes can reach different stages at the same time. The parent remains the place to judge whether the complete connection works, including any acceptance criteria that span several children.']),
    section('split', 'Choose between a new child and a split', ['Use a new sub-route for a fresh, focused piece of work. Use Split when an existing brief needs several separately reviewable outcomes: split copies the source brief and checklist into new, unassigned Ready Routes while retaining the original as their parent. Rewrite each copied brief so it describes that child’s actual scope, and review the copied owner and reviewer before relying on them.', 'Splitting does not copy an accepted result or authorize an agent. Copied acceptance checkboxes start unchecked, and the new Routes still require their own evidence. Duplicate is different from Split: it makes an independent copy rather than treating the copy as a smaller part of the source. Add dependencies only when one outcome truly needs another; siblings do not block each other merely because they share a parent.']),
    section('working', 'Work on the child without losing the larger purpose', [], { steps: ['Open the parent and read its overall outcome and exclusions.', 'Choose the child that owns the next deliverable, rather than editing several similar briefs.', 'Give that child a clear owner, reviewer, and observable acceptance criteria.', 'Record progress and decisions on the Route they actually describe.', 'Review the exact output version and deliberately update the child’s stage.', 'Return to the parent to check integration work and remaining acceptance criteria.'], note: 'Creating, linking, ordering, or opening sub-routes does not launch agents, change provider permissions, or accept an output.' }),
    section('create-sub-route', 'Create or attach the right Route', ['Open a Route and find its Sub-routes section. Choose New sub-route, enter a title and focused description, select priority, and create it. The new Route inherits the parent’s project and team, starts in Backlog, and does not start an agent. Open it afterward to set the agreement and move it to Ready when the brief is actionable.', 'Use Attach existing route when the work already exists as an unparented Route in the same project and team. Attachment preserves its status, agreement, and descendants; it does not make a copy. The picker shows eligible visible candidates, and the server checks the selection again. If the expected Route is absent, check its current parent, project, team, archive state, and your access instead of making a duplicate.']),
    section('organize-sub-routes', 'Move the relationship without rewriting the work', ['Choose parent or Change parent moves the current Route and its attached descendants beneath a different parent. Detach from parent makes it a top-level Route in the same project and team while keeping its own descendants attached. Use the child-row Detach action when you are working from the parent. These changes do not rewrite the Route’s brief or move it into another project.', 'Use the up and down controls to order immediate children. This is sibling order, not a priority, dependency, due date, or execution queue. The hierarchy supports at most five levels including the root and up to 100 immediate children per Route. Cycles, self-parenting, and cross-project or cross-team links are rejected. Detach the relevant relationships explicitly before moving work to another project or team.']),
    section('leaf-progress', 'Read progress without counting the same work twice', ['Leaf progress counts the smallest Routes in the hierarchy: a leaf has no children. A parent with children is not counted again alongside those children. Done active leaves contribute to completion; unfinished active leaves remain outstanding. Cancelled and archived leaves are shown separately and do not improve the completed percentage. A hierarchy with no active eligible leaves has no meaningful completion ratio.', 'The parent’s lifecycle is still a separate decision. Completing children does not mark the parent Done automatically. Before completing a parent, finish or cancel its unfinished descendants, including unfinished archived descendants: hiding work is not completing it. Reopen a completed ancestor before reopening a resolved child. Use the parent acceptance criteria to judge the integrated result, even when every leaf is Done.']),
    section('recover-hierarchy', 'Recover deliberately from changes and missing access', ['A hierarchy operation uses the revision you reviewed. If another edit changes the structure, status, or relevant scope, refresh the hierarchy and inspect the new state before submitting again. An uncertain delivery keeps the same request for Retry same request, preventing a retry from silently creating another child. Do not replace an uncertain request with a new one merely because the response was delayed.', 'Archiving a parent does not automatically archive its children. The relationship remains, and an active child can show that its parent is archived. Restore ancestors before restoring archived children or adding work beneath them. Show archived sub-routes when you need to inspect the complete immediate list. Permanent deletion of a parent is blocked until all its children, including archived ones, are explicitly detached.', 'Restricted or invalid legacy relationships can make the complete hierarchy unavailable. Frondose shows an access or integrity warning instead of presenting a complete progress figure from partial data. Where offered, Repair by detaching this route removes the broken parent link without deleting its descendants. Review the resulting structure afterward; repair does not grant access to hidden Routes.']),
    section('backup-hierarchy', 'Keep hierarchy intact in a workspace backup', ['Workspace JSON export includes Route agreements, parent relationships, and sibling positions within the records you can export. Import creates a new workspace with new IDs and remaps the relationships; it does not overwrite the original workspace. Sibling order is retained. Invalid cycles, scope mismatches, and excessive hierarchy depth are rejected rather than imported as a seemingly valid tree.', 'A backup is not an execution plan. Restoring Routes does not launch agents, restore local folder permissions, or verify their recorded completion. Review the imported project, team, agreements, and evidence before resuming work. Consult the export guide for other limits, including uploaded resource files that are not bundled into workspace JSON.']),
  ], { related: ['route-agreements', 'labels-statuses', 'outputs', 'updates-replies', 'import-export'], appLink: { view: 'tasks', label: 'Open Routes' }, image: 'projects' }),

  article('route-agreements', 'projects-routes', 'Owners, dependencies, and acceptance', 'Agree on who decides and what evidence is required.', [
    section('agreement', 'Define the work agreement', ['A Route can record a human owner, required reviewer, expected output type, acceptance checklist, parent Route, and blocking dependencies. These fields make handoffs less ambiguous. An owner coordinates the outcome; a reviewer checks the deliverable. Neither field is a grant of provider or file permissions.']),
    section('checklist', 'Write observable criteria', ['Prefer “The empty state links to Create project and works at 390px” to “Make it good.” Good criteria tell a reviewer what to inspect. Keep the checklist near the Route so an output review can refer to the same agreement instead of relying on a separate chat message.']),
    section('dependencies', 'Use dependencies deliberately', ['A parent groups work; a blocking dependency means the outcome cannot proceed without another Route. Cycles are rejected. When scope changes, check whether a blocker is still real and whether target dates remain consistent.'], { steps: ['Choose the owner and reviewer.', 'Specify the output and acceptance criteria.', 'Add only necessary dependencies.', 'Review the submitted output, then deliberately update the Route stage.'] }),
    section('parent-agreement', 'Keep parent and child acceptance separate', ['The parent agreement describes the combined result. A sub-route agreement describes that child’s contribution. A completed child does not prove that the parent’s integration, usability, or release criteria have been met. Likewise, marking a parent Done is not evidence that every child output was reviewed. Check the hierarchy and the exact deliverables before making a completion decision.', 'Do not use a parent link as an access grant or as a request to start work. A person must already have the necessary access to the related Routes; an agent still needs explicit execution authorization. Human owner and reviewer names explain responsibility, but recording a name does not authenticate that person or change workspace permissions.']),
    section('scope', 'Choose hierarchy and dependencies for different reasons', ['A parent-child link expresses containment: this smaller result contributes to that larger outcome. Parent and child therefore stay in the same workspace, project, and team. A dependency expresses a prerequisite and may point to other accessible work in the workspace. Do not add both relationships by habit; explain what must be available before the dependent Route can proceed.', 'Hierarchy changes check the affected Routes again when saved, including existing descendants. They cannot use the authority of an accessible parent to expose or reorganize restricted work. A cycle in either the parent graph or the dependency graph is rejected. If a link is unavailable, inspect scope and access rather than copying an inaccessible ID into another form.']),
    section('completion', 'Review the remaining leaves before marking a parent Done', ['Use leaf progress to avoid counting a parent and its children as separate completed contributions. Check Done, unfinished, cancelled, and archived leaves individually: cancellation explains scope that will not be delivered, while archive describes visibility. Neither is an accepted output. A parent cannot be completed while a descendant remains unfinished, even when that descendant is archived.', 'When a completed branch needs more work, reopen the completed ancestors first, then reopen the child or add the new work. This keeps the recorded parent outcome consistent with its unfinished contribution. The system never completes the parent automatically or treats a successful agent session as acceptance. Review the evidence and explicitly change the stage.']),
    section('handoff', 'Leave a handoff another person can act on', ['For a child Route, state what changed, what was checked, what was not checked, and what the parent still needs. Link the actual output or supporting document instead of replacing evidence with a stage change. If the result introduces a new dependency or changes scope, update the agreement deliberately rather than assuming that a comment rewrites the plan.', 'Use Updates & replies for the discussion attached to that Route. Publishing a child update does not publish the same entry on the parent; link to the child when writing a parent-level summary. Mentions do not contact or activate an agent. Important criteria belong in the agreement or project brief as well as in the conversation.']),
  ], { related: ['routes', 'outputs', 'output-review', 'milestones-timeline'] }),

  article('labels-statuses', 'projects-routes', 'Labels and custom workflows', 'Create useful vocabulary without losing lifecycle meaning.', [
    section('labels', 'Labels describe; statuses locate', ['Labels describe a Route or project: a work area, audience, or type of change. Statuses describe where it is in a lifecycle. Keeping these separate makes filters clearer. Use a small vocabulary that people can apply consistently instead of creating a new label for every title.']),
    section('configure', 'Configure the vocabulary', [], { steps: ['Open Settings and choose the Route or Project Labels page.', 'Add a descriptive label, color, optional group, and explanation.', 'Use Workflow for Routes or Statuses for projects to customize stage names.', 'Choose the correct underlying lifecycle category for each stage.', 'Apply the labels and stages to real work, then test the corresponding filters.'] }),
    section('meaning', 'Preserve the meaning of completion', ['A custom name should not obscure whether work is active, blocked, under review, or complete. Route and project labels are separate collections because the same vocabulary does not always fit both. Color is a visual aid; the name and description should carry enough meaning without it.']),
  ], { related: ['routes', 'projects', 'saved-views'], appLink: { view: 'settings', id: 'route-labels', label: 'Manage Route labels' } }),

  article('templates-recurrence', 'projects-routes', 'Templates and repeating Routes', 'Reuse a strong starting point without triggering unattended work.', [
    section('templates', 'Save the repeatable part', ['Route templates hold a brief or checklist, starting stage, priority, and suggested agents. Project templates provide a brief, goal, and milestone titles. Chat templates supply participants and an opening note. Each can also define custom questions whose answers are saved with the created item. Creating content from a template starts with saved structure; it does not start an agent.']),
    section('repeating', 'Generate due work deliberately', ['Repeating Routes store an interval and date schedule with pause and resume controls. When an occurrence is due, generation is an explicit action. Frondose protects against replaying the same request into duplicate work, but the current feature is supervised recurrence rather than a background scheduler.']),
    section('practical', 'Keep templates adaptable', [], { bullets: ['Include a short scope and an acceptance checklist.', 'Leave room for the current source links and constraints.', 'Review suggested assignees instead of assuming they are still appropriate.', 'Pause recurring work when the underlying need ends.', 'Check generated Routes before preparing execution.'], note: 'Neither a repeating Route nor a template schedules an AI run or sends a reminder automatically.' }),
  ], { related: ['routes', 'coordination'], appLink: { view: 'settings', id: 'repeating', label: 'Open repeating Routes' } }),

  article('coordination', 'projects-routes', 'Coordinate plans and handoffs', 'Manage prerequisites and next steps while keeping launches deliberate.', [
    section('plans', 'Make the sequence explicit', ['Coordination holds work plans, prerequisite gates, human or agent assignments, queues, handoffs, requests, goals, and templates. A plan is useful when several outcomes depend on one another. Describe the result of each step and the evidence the next step needs, rather than only naming an agent.']),
    section('prepare', 'Preparation is not dispatch', ['Preparing a plan step opens a session form for review. You still choose to launch it. Linking the resulting run back to a step is currently explicit, not automatic. Record the result and handoff so later work can distinguish a completed run from an accepted deliverable.']),
    section('supervision', 'Understand pause and rules', ['Pausing a plan prevents further preparation; it does not terminate already running sessions. Route automation rules are previewed and manually applied to matching Routes. They do not run in the background, send external messages, or launch agents.'], { note: 'Requests can become linked Routes after acceptance. Goals derive progress from active leaf Routes in their linked projects, without counting parents again; they do not independently verify an outcome.' }),
  ], { related: ['route-agreements', 'session-progress', 'outputs'], appLink: { view: 'operations', label: 'Open Coordination' } }),

  article('chat-basics', 'chats-agents', 'Conversations and notes', 'Keep discussion useful and make the recipient explicit.', [
    section('rumbo-agent', 'Frondose', ['Open Frondose from the sidebar for its Conversation, Activity and Scheduled sections. A disconnected account can still read accessible history and activity. Choose a connected agent identity, prepare a request, then explicitly Send; ordinary Chat captures exact server context on Send. Elevated tools still require explicit inspection. Creating a conversation, typing or opening a section never starts a provider.', 'Settings → Frondose controls identity and execution/context defaults. Configured model IDs do not guarantee account entitlement. Preferences never authorize access. The optional low-risk policy permits safe new Routes and self-membership links; other supported changes remain pending proposals. Paid launches, permissions, destructive and external effects retain their separate confirmations.', 'Ask Frondose on a document, update, Route, project or Workbench prepares a source-linked draft. Mentioned connected agents in published updates and replies have an explicit Ask control targeting that identity. /frondose also prepares a draft. Canonical source IDs are checked on the server; unsaved source edits are not silently included. Mentions and handoffs do not launch work.']),
    section('assistant-activity', 'Activity and Scheduled', ['Activity shows recorded agent runs in this workspace, status/search filters, runtime approval gates, conversation links and outputs for review. A completed invocation is not proof that the requested result was achieved. Needs you covers blocked, failed or runtime approval-gated runs; review completed conversations for action proposals.', 'Stop run affects only the chosen run and does not undo changes or cancel schedules. Scheduled uses the same real schedules as Settings, with occurrence history, timing changes, pause/resume and explicit cancellation. Stale reads cannot overwrite a confirmed change, and loss of source access hides protected schedule details.', 'Connected agents can propose one-off, daily or weekly prompts and creator-owned schedule pause, resume, reschedule or cancellation. Proposals are not saved changes: inspect the exact prompt/model/time/timezone/repetition and confirm. Changing a schedule pins its current version and does not change its saved prompt, context or recipient. Each provider occurrence can be billed. Repeating prompts reuse the original reviewed snapshot, not fresh workspace state.']),
    section('past-conversations', 'Reuse a past conversation', ['In a conversation, choose Select context sources → Past conversations. Search a phrase, select individual messages and create a snapshot. Search is bounded lexical matching over readable messages in this workspace, not semantic research or ChatGPT/Claude account-history access. Only selected messages are included; attachments and adjacent messages are not copied.', 'Frondose resolves canonical content and saves an immutable snapshot, up to 15 KB, for explicit Send or a separately confirmed schedule. Search, selection and snapshot creation never call a provider. Current and historical source permissions are checked on search, snapshot creation/reload, inspection, delivery and derived-history reads.', 'Draft browser storage keeps the snapshot ID rather than protected source text. Restoring a draft reauthorizes the snapshot; unavailable context blocks sending until removed or successfully reloaded. Approved scoped agent memory is separate and retains source-run permissions. This is explicit retrieval, not autonomous cross-chat memory.']),
    section('notes', 'A chat can be useful before AI', ['A conversation can hold planning notes and discussion without contacting a provider. The composer distinguishes saving a note from sending a message. New conversations have exactly one responding agent; once bound, that identity cannot be changed. Create another conversation to work with a different agent. Legacy participants and message histories remain readable; editing an older title does not silently select a future responder. Check the recipient and access mode before every consequential send.']),
    section('workflow', 'Start a conversation', [], { steps: ['Create a chat, give it a recognizable title, and choose one responding agent.', 'Optionally associate it with a project.', 'Add a note, or check that the chosen agent’s connection is ready.', 'Inspect the context and access mode.', 'Send deliberately and follow the activity shown with the reply.'] }),
    section('layout', 'Make room for the conversation', ['Open conversations use a single working pane. Recent conversations remain in the global sidebar; the Conversations index provides search for older discussions.'], { note: 'Image attachments are note previews, not guaranteed CLI vision input. Text attachments are bounded and can be truncated when included in model context.' }),
  ], { related: ['chat-access', 'chat-context', 'message-actions'], appLink: { view: 'chats', label: 'Open chats' }, image: 'chats' }),

  article('chat-access', 'chats-agents', 'General chat and project access', 'Choose what a reply is allowed to work with.', [
    section('general', 'General chat needs no folder', ['General chat uses the conversation and supplied text context. Its CLI execution takes place in a private temporary directory with restricted tool configuration. Frondose does not silently substitute your home folder, its own checkout, or private workspace storage as the working project.']),
    section('project', 'Project work is an explicit choice', ['Reading or coding in project files requires a linked project or agent working folder and the chosen execution mode. A folder link is not needed for planning alone. Before enabling project work, verify that the folder is the intended repository and that the request explains what changes are allowed.']),
    section('check', 'Check the boundary before sending', [], { bullets: ['Use General chat for discussion based on the context you provide.', 'Use project access only when files need to be inspected or changed.', 'Keep secrets out of prompts and attachments.', 'Review retries with the same care as the first send; the selected mode is retained.', 'Do not assume an agent profile’s friendly name changes its underlying provider permissions.'], note: 'Project-file execution permissions are separate from approval of a proposed Frondose workspace action.' }),
  ], { related: ['chat-basics', 'agent-actions', 'workbench-safety'] }),

  article('chat-context', 'chats-agents', 'Choose conversation context', 'Inspect what will travel with a message.', [
    section('sources', 'Select useful sources', ['The Chat context dialog shows selected sources, connected work, agents, and the optional working folder. You can choose documents, memory, or a context pack and capture an immutable text snapshot. Selecting sources alone does not contact an agent. The snapshot preserves what you reviewed even if the original source later changes.']),
    section('review', 'Review before sending', [], { steps: ['Open Context in the conversation.', 'Find the relevant documents, memory notes, or packs.', 'Choose only the sources needed for the current question.', 'Capture and inspect the selected text.', 'Check the recipient and access mode, then send explicitly.'] }),
    section('bounded', 'More context is not always better', ['Long context can obscure the actual request and may be truncated by budget limits. Prefer the specific decision, constraint, or source excerpt the work requires. A document title in the agent’s workspace overview is not the document’s complete content; select the content explicitly when it matters.'], { note: 'Moving a conversation to a different project can change its relevant context. Review warnings and sources instead of assuming previous context remains appropriate.' }),
  ], { related: ['context-snapshots', 'agent-awareness', 'agent-memory'] }),

  article('message-actions', 'chats-agents', 'React, select, and reuse messages', 'Turn useful conversation into connected work.', [
    section('react', 'Use reactions with clear meaning', ['Hover over a message or focus its actions to reveal React. The picker separates line Icons, native Emojis, and uploaded My Emojis, with search and categories. Upload your workspace images in Settings → Emojis; the chat composer also has an Insert emoji control. Icons default to neutral gray and support preset colors or a custom six-digit hex tint. Native emoji colors are supplied by the platform. Reactions persist stable catalog identifiers rather than arbitrary uploaded SVG.']),
    section('select', 'Select messages deliberately', ['The message actions menu includes Select message. Multi-selection lets you copy or export the chosen messages, then cancel selection when finished. This is different from quoting a message into the composer or replying in a thread. Use quotation when you want the next answer to address a specific passage.']),
    section('reuse', 'Keep an idea connected to its source', ['Message actions can create a Route or project document, save an output or memory, bookmark a message, and branch a conversation from that point. A branch preserves a starting history without dispatching an agent. Review generated object details before treating an extracted message as an agreed brief.']),
  ], { related: ['chat-basics', 'outputs', 'routes', 'agent-memory'] }),

  article('agent-profiles', 'chats-agents', 'Agent profiles and Personalization', 'Describe a collaborator separately from its provider connection.', [
    section('profile', 'Choose the identity you need', ['Your Agents holds personalized profiles with a name, description, picture and Personalization. AI Providers holds direct provider identities using the provider’s name and mark, without custom Personalization. Choose Create agent or Connect AI provider explicitly; the saved identity type cannot be switched. Both use Frondose-owned conversations. Creating either identity does not authorize an account or start work.']),
    section('setup', 'Create a useful collaborator', [], { steps: ['Create an agent with a clear name and optional description.', 'Choose a provider, then one of its supported connection methods: API key, supported browser authorization, or Computer (CLI). Not every provider offers every route.', 'Select an account connection, or use Connect / manage to configure one. A connected-looking catalog entry is not proof of readiness.', 'For a browser/API connection, load and choose an explicit chat model. Add an optional picture and write Personalization for the work you need.', 'Save the profile. Use a small, explicit task to evaluate it; saving never starts AI work.'] }),
    section('native-history', 'Native history is not connected', ['Direct provider identities do not enable native CLI history listing, import, persistent-session continuation or external-history refresh. Those capabilities are not implemented in Frondose. Neither identity type reads ordinary ChatGPT or Claude website histories. Existing provider-native storage behavior is not a guarantee of ephemeral sessions.']),
    section('limits', 'Do not confuse instructions with permissions', ['Instructions guide behavior; they do not grant access, authenticate an account, or enforce a security boundary. Multiple profiles share their provider connection and account limits while keeping independent instructions and histories. They are not separate provider accounts, and Frondose does not import ordinary ChatGPT or Claude chat history.', 'Saved prompt presets remain separate from versioned Skills. Model and supported reasoning defaults are forwarded to the runner, but account availability is controlled by the provider. Review the Context Inspector before each live launch; Area defaults and saved preferences are not grants. Agent Studio, Skills and Context Packs reuse these same access boundaries.']),
  ], { related: ['provider-connections', 'agent-awareness', 'agent-actions'], appLink: { view: 'agents', label: 'Open agents' } }),

  article('agent-awareness', 'chats-agents', 'Workspace-aware agents', 'Understand what the agent can know about Frondose without giving it unrestricted access.', [
    section('overview', 'A fresh, bounded overview', ['Eligible live replies can receive readable project, Route and Area summaries, document/conversation titles, milestones, safe server-saved settings, label/status/template configuration and active custom-emoji shortcodes. The exact Context Inspector shows included sources and limits. This is not a complete database dump or continuous observation. Document titles do not expose the full documents; select their content explicitly when needed.', 'Only the current user’s permitted information is included. Credentials, security grants, private drafts, template answers/defaults and browser-local choices such as sidebar layout or Field Defaults are excluded. Server settings retain their private owner boundary when replies are reused. A missing or omitted source is unknown, not evidence it does not exist.']),
    section('expressions', 'Reactions, emojis and conversation style', ['The agent can see reactions on messages already included in its current conversation or explicitly selected past-message context. It receives semantic reaction names/Unicode and allowed custom-emoji metadata, not image blobs, bookmarks or private drafts. Archived custom reactions remain historical expressions, not reusable shortcodes.', 'Frondose can respond naturally, match your language and use Unicode emojis or listed active custom shortcodes where useful. Your saved communication preferences still apply. This is guidance to the connected model, not a guaranteed personality or a claim that it is human. A reaction is never permission, approval, an instruction or proof that work finished.']),
    section('control', 'Control awareness', ['Settings → Agent awareness controls future overview and proposal injection. Disable it when a conversation should not use that workspace overview. Approved saved memory has a separate control. Extremely long prompts can consume the available context budget and omit awareness, so do not rely on it as the only place a critical task constraint is stated.']),
    section('trust', 'Context is not authority', ['Workspace descriptions, settings and memory are reference data, not authorization. Safe changes may follow the explicitly enabled low-risk policy; other workspace changes remain proposals. Native tools are a separate inspected per-run opt-in, not a consequence of awareness. An agent cannot approve its own proposal, grant itself tools or change its access policy through a reply. Without a ready AI connection, opening Frondose asks you to connect; saved history remains readable.']),
  ], { related: ['agent-memory', 'agent-actions', 'chat-context', 'scheduled-work'], appLink: { view: 'settings', id: 'awareness', label: 'Open Agent awareness' } }),

  article('agent-memory', 'chats-agents', 'Persistent agent memory', 'Keep reviewed information useful across future replies.', [
    section('scope', 'Remember the right thing at the right scope', ['Approved agent memories are scoped to the workspace, the agent, and optionally a project. A project-specific convention should not become a global assumption for unrelated work. Useful memories are durable preferences, stable constraints, or reviewed decisions; temporary guesses and credentials do not belong there.']),
    section('review', 'Review and forget', ['Agents can propose memory creation as a reviewed action. Inspect the proposed text and scope before approving it. Chat context and Agent awareness settings expose saved memory so you can see what persists and explicitly forget entries that are no longer appropriate. Disabling saved memory excludes it from subsequent prompts without erasing existing conversations.']),
    section('distinction', 'Memory is not a source of truth by itself', ['Memory records can become outdated. For evidence-sensitive work, attach current source material or a reviewed context snapshot and state which information takes precedence. Library knowledge adds types, rationale, and review dates when you need a more structured record.'], { note: 'Agent memory persists across restarts but is not currently included in workspace JSON export/import. Preserve database backups if these records are important.' }),
  ], { related: ['agent-awareness', 'agent-actions', 'knowledge-decisions', 'import-export'] }),

  article('agent-actions', 'chats-agents', 'Review proposed Frondose actions', 'Let agents suggest changes while keeping execution under your control.', [
    section('supported', 'Proposals describe exact changes', ['Completed agent replies can propose allowlisted preference updates, edits to projects, Routes, or documents, reversible archives, and persistent memory creation. Frondose presents the target and proposed values in a review dialog. The proposal is not the change: every supported mutation still requires a human decision. Preference changes affect user-global settings across workspaces; record edits and memories remain workspace-scoped.']),
    section('review', 'Check before approving', [], { steps: ['Read the target name, scope, and proposed values.', 'Check that the change matches your original request.', 'Consider whether other work has changed since the proposal was prepared.', 'Approve or reject the request explicitly.', 'Read the outcome; approval does not automatically start a new paid run.'] }),
    section('guards', 'What the server checks', ['Frondose rejects unsupported actions, cross-workspace targets, invalid parents, stale values, inappropriate active-session changes, and repeated decisions. Agent text cannot approve requests or grant permissions. File changes made under a separately chosen project execution mode are governed by that mode, not by this workspace-proposal dialog.'], { note: 'A rejected stale proposal should be reviewed against current state, not forced through by repeatedly clicking approval.' }),
  ], { related: ['agent-awareness', 'agent-memory', 'chat-access'] }),

  article('session-progress', 'chats-agents', 'Progress, failures, and retries', 'Read execution state without confusing activity with the final result.', [
    section('activity', 'Progress is separate from the response', ['When a provider identifies commentary, Frondose presents it as activity rather than a sequence of full final messages. The activity folds after completion and remains available to reopen. The final response is shown separately. Frondose-specific action proposals retain their own review controls instead of being treated as ordinary text instructions.']),
    section('failures', 'Inspect the cause before retrying', ['Failures show a short explanation with expandable diagnostics. Configuration problems, expired access, rejected provider requests, and empty replies require different fixes. A 403 response still needs the provider access problem resolved; changing the display does not fix authorization. Frondose does not silently replace a failed real reply with simulated content.']),
    section('retry', 'Retry with the original intent', ['The send pipeline preserves idempotency information through uncertain delivery, navigation, and reload to reduce accidental duplicate requests. Check whether a run is still active before retrying. Queued follow-ups are drafts, not automatically launched work. Stopping a run does not undo any changes it already made.']),
  ], { related: ['provider-connections', 'chat-access', 'output-review'], appLink: { view: 'work', label: 'Open sessions' } }),

  article('workbench-overview', 'workbench', 'Your project Workbench', 'Bring project files, Git, terminals, and previews into one working area.', [
    section('environment', 'Start with a project', ['Workbench is project-scoped. A project without a linked folder still has a planning overview. Choosing a working folder enables scoped file browsing and Git inspection, plus deliberate command execution. Opening Workbench does not run package scripts, launch agents, or change the project’s files.']),
    section('panels', 'Use only the panels you need', ['The environment combines a file tree, filename and content search, text previews, pins, Git status and diffs, branch and worktree inspection, and real terminals. Per-Workbench settings remember panel visibility, wrapping, terminal font size, and terminal count limits. Keep the arrangement focused on your current question rather than opening every panel.']),
    section('workflow', 'A practical first pass', [], { steps: ['Choose the intended project and verify its linked folder.', 'Inspect the file tree and current Git changes.', 'Open the relevant file or diff.', 'Review a command before confirming its launch.', 'Use the explicit localhost preview checker when you have a running preview.'], note: 'Workbench is not a deployment service, and its terminals are not sandboxed.' }),
  ], { related: ['files-search', 'git-worktrees', 'terminals', 'workbench-safety'], appLink: { view: 'workbench', label: 'Open Workbench' } }),

  article('files-search', 'workbench', 'Files, search, and previews', 'Inspect a linked project without losing its working context.', [
    section('browse', 'Start from the linked root', ['The file tree and file APIs are scoped to the project’s linked root. Filename search is useful when you know a module or document name; content search helps when you know a phrase or symbol instead. Text previews let you inspect a result before deciding to open another tool or run a command.']),
    section('pins', 'Keep recurring references close', ['Pin files you return to during the current work, such as a specification or configuration file. Wrapping is a display preference for long text, not a content modification. Check the path before drawing conclusions from a file, especially when similar names exist in a monorepo or a separate worktree.']),
    section('limits', 'Protected does not mean invisible everywhere', ['The service rejects traversal and selected sensitive/private paths for file access. Those protections do not turn arbitrary terminal commands into a sandbox: a shell runs under the OS user’s permissions. Do not paste secrets into search boxes, shared notes, or agent prompts simply because a file exists inside the linked project.']),
  ], { related: ['workbench-overview', 'terminals', 'workbench-safety'] }),

  article('git-worktrees', 'workbench', 'Branches, diffs, and worktrees', 'Inspect repository state and isolate a working checkout deliberately.', [
    section('shared-changes', 'Changes and review throughout Frondose', ['The same comparison view appears in Workbench → Changes, the project Changes tab, a Route’s Changes & review section, completed chat run results, session details, and Documents → Revision comparison & review. Chat context also offers a conversation-level review section. Library output comparisons and knowledge revision comparisons use this viewer too. Fenced code in messages and documents uses your code style; quoted diff/patch blocks are labeled unverified and do not claim repository provenance. GitHub connection code browsing provides pull-request reviews linked to a project. These are embedded views, not shortcuts that move you into another tool.', 'Choose Working changes for unstaged and untracked files, Staged changes for the index, or Branches or commits for an exact two-reference comparison. Enter a branch, tag, or full commit ID; advanced Git revision operators are intentionally not accepted. Comparisons never stage, revert, commit, push, switch branches or merge.']),
    section('reading-diffs', 'Read files and changed lines', ['Each file has a type badge, path, change status, and added/deleted line counts. SQL uses a database icon; JavaScript and TypeScript use language badges. Renames retain their old path. Select a file in the list to move to it, filter the list by path, or search the displayed code. Green rows are additions and red rows are removals. The optional +/− markers distinguish changes without relying only on color.', 'Unified and side-by-side views, wrapping, line numbers, syntax colors, tab size, font and size follow Settings → Code & reviews. Viewer controls update the same personal preferences. Hide whitespace suppresses paired whitespace-only changes visually; it does not alter the saved patch or line coordinates. Expand unchanged sections individually or use Expand context. GitHub only supplies bounded context: lines absent from its patch cannot be expanded.']),
    section('saved-reviews', 'Save one exact comparison', ['Load comparison to inspect the source, then Save review snapshot to preserve it. Frondose rechecks the source before saving; if it changed, refresh and inspect the new version first. Saved snapshots are listed on their target and aggregated in the linked project. Copy review link opens that saved version for people with access; switch to the owning workspace if necessary. Check for newer changes reports whether a local or GitHub source still matches; old comments remain attached to their saved snapshot.', 'Use the + button on a line to write a Frondose review comment, then mark individual files Reviewed. Reviewed state is personal to the signed-in actor, while comments retain author attribution and exact old/new line coordinates. This is not an approval of the Route, permission to execute code, or a GitHub review submission.']),
    section('github-review', 'Review a GitHub pull request', ['Connect GitHub, enable reading, and select the repository in connection settings. In Changes & review select GitHub pull request, choose that connection and repository, and enter the PR number or find an open PR. Frondose reads the pinned base/head, file patches, reviews, line discussions and check results. If the PR changes during loading, reload instead of mixing versions.', 'Write GitHub review opens an explicit external submission dialog with Comment, Approve or Request changes. Enable Submit pull request review in the connection first. Workspace permissions and owner approvals still apply. Frondose checks the head commit again before posting; an approval for an old head is not silently applied to new code. Select a line and choose Review this line on GitHub to attach the discussion to an exact old/new line. Retrying the same payload in the same browser tab reuses its submission key, including after a reload; an uncertain result must be checked on GitHub before starting a new request. Reading a PR does not merge it or send a review. Missing checks are reported as unavailable, not successful.']),
    section('run-review', 'Review observed agent changes', ['Future live project sessions in their accessible linked default Git folder attempt a bounded before/after capture. Open the saved observation from the session, the chat run result, or its linked project. Changes already present before the run are not presented as new work. Concurrent edits by people or other agents can still appear; a snapshot is evidence of folder state, not evidence of who authored each line. General chats, simulations, old runs, interrupted capture and unlinked or inaccessible folders do not gain invented diffs.', 'From a selected line, Prepare agent follow-up creates an editable request with the comparison identity and line text. Choose a chat and recipient and save it to Follow-up drafts. Open that draft in the chat composer, check context and access, then send explicitly. Viewing code, typing an @mention in a comment, or saving the draft never starts an agent.']),
    section('review-limits', 'Scope and current limits', ['Local comparisons require the repository root, stay inside its linked folder, and exclude private paths and symlinks. Snapshots are bounded to 200 files and approximately 2 MB of patch content, with a 300 KB per-file patch limit; binary and oversized previews have explicit explanations. GitHub PR files are limited to 200 and its reviews, comments and checks to 100 each. Large visible diffs render in batches of 1,000 rows; use Show next to continue. A limited review must not be treated as complete.', 'Review data persists in Frondose’s database. The workspace JSON archive does not yet include review snapshots or their discussions. Code-style preferences remain browser-personal. Live-provider verification is separate from fixture tests; availability depends on the actual GitHub authorization and selected resources.']),
    section('inspect', 'Read the current state first', ['Workbench shows Git status, diffs, branches, and worktrees for the linked repository. Inspect existing uncommitted changes before starting a new piece of work. A branch is a Git reference; a worktree is another checkout with its own working files. They solve related but different problems.']),
    section('create', 'Create a worktree intentionally', ['Worktree creation is an explicit action. The target must belong to the project’s repository, and creating it does not silently switch the project’s working folder. Confirm which checkout an agent or terminal will actually use before running commands; a worktree existing in a list is not proof that the current session is using it.']),
    section('review', 'Review changes before integration', [], { bullets: ['Check the current branch and working location.', 'Distinguish your changes from pre-existing edits.', 'Inspect the diff and run relevant verification.', 'Keep output approval separate from Git merge or publication.', 'Do not assume that switching visual panels changes Git state.'], note: 'Project folder changes are restricted while related work is active. Finish or stop that work before changing its environment.' }),
  ], { related: ['terminals', 'workbench-safety', 'output-review'] }),

  article('terminals', 'workbench', 'Terminals and saved commands', 'Run real commands with an explicit launch and visible process state.', [
    section('real', 'A terminal is an active process', ['Workbench terminals use a real PTY, with keyboard input, resizing, stopping, retained output, and reload recovery. They are not simulated transcripts. Saved commands and discovered package scripts make common tasks easier to find, but launching one still requires confirmation. Opening the page itself does not execute commands.']),
    section('run', 'Check before launch', [], { steps: ['Verify the selected project and working folder.', 'Read the complete command, including arguments and shell operators.', 'Confirm only if its side effects are appropriate.', 'Watch the output and process state.', 'Stop the process explicitly when it is no longer needed.'] }),
    section('lifecycle', 'Closing a panel is not stopping work', ['A hidden terminal can still have a running process. Server restart ends live processes even though saved history remains. Output and process counts are bounded, so terminal history is not an unlimited audit archive. Stopping a process prevents further work; it does not reverse file changes, network calls, or other effects that already happened.']),
  ], { related: ['workbench-safety', 'git-worktrees', 'workbench-overview'] }),

  article('workbench-safety', 'workbench', 'Execution and preview boundaries', 'Understand what the current environment protects—and what it does not.', [
    section('permissions', 'Commands use the OS user’s permissions', ['Workbench terminals run as the current OS user. They are not containers or isolated sandboxes. The file/Git APIs have linked-root and path protections, but an arbitrary shell command can have broader effects. Treat destructive commands, credential access, and network operations with the same care you would in your own terminal.']),
    section('preview', 'A preview is not a deployment', ['The preview checker validates an explicitly chosen localhost port. Use it to inspect a development server you intended to start. It does not publish the project or create public hosting. A frontend build or static host alone also does not provide Frondose’s server API, database, provider execution, or PTY runtime.']),
    section('safe-habits', 'Keep the boundary visible', [], { bullets: ['Verify paths before running file-changing commands.', 'Use disposable fixtures for risky experiments.', 'Do not infer isolation from a project name or a permission label.', 'Review changes independently after a run.', 'Keep the current API on its intended trusted host; public access needs additional architecture and authorization.'] }),
  ], { related: ['terminals', 'service-boundaries', 'developer-architecture'] }),

  article('documents', 'knowledge', 'Documents and living briefs', 'Keep explanations editable and link them to the work they support.', [
    section('purpose', 'Use a document for evolving text', ['Documents are useful for project briefs, team guidance, research notes, and explanations that need a stable home. They have direct app pages and links, search, and favorites. A document can change as your understanding improves; a context snapshot preserves a reviewed copy of its text at one point in time.']),
    section('write', 'Make documents easier to use', [], { steps: ['Give the document a title that describes the question or decision.', 'State its purpose and the scope of the information.', 'Separate current decisions from unresolved questions.', 'Link it to the relevant project or team.', 'Select it explicitly when a chat needs its content.'] }),
    section('freshness', 'Avoid accidental authority', ['An old document may still be searchable or appear as a title in workspace awareness. That does not mean every statement is current. Record dates and sources in the content when freshness matters. If an agent must use a particular version, capture reviewed context rather than assuming it will read the latest complete document automatically.']),
  ], { related: ['context-snapshots', 'knowledge-decisions', 'chat-context'], appLink: { view: 'documents', label: 'Open documents' } }),

  article('knowledge-decisions', 'knowledge', 'Knowledge and decisions', 'Record facts, rationale, and preferences with a review lifecycle.', [
    section('types', 'Distinguish kinds of knowledge', ['Library separates facts, decisions, preferences, and instructions. Facts should point to evidence. Decisions need rationale and scope. Preferences describe how you want work done. Instructions tell a future reader how to act, but remain subordinate to actual permissions and the current task. Choosing the right type helps avoid treating an opinion as evidence.']),
    section('lifecycle', 'Review before reuse', ['Entries support Draft, Approved, and Superseded states, a source or rationale, and a review date. Editing approved content returns it to draft. Archive removes an entry from active use without rewriting older snapshots. For context capture, use approved knowledge that is still relevant to the question.']),
    section('history', 'Restore with care', ['Revision history uses recorded change-log entries, including pre-edit text. Restoring a revision places that text in an unsaved draft so you can inspect it before saving. History begins when change logging exists; it is not reconstructed retroactively or presented as tamper-proof evidence. Snapshot backlinks show where an entry was captured.']),
  ], { related: ['context-snapshots', 'agent-memory', 'outputs'], appLink: { view: 'library', label: 'Open Library' } }),

  article('context-snapshots', 'knowledge', 'Reviewed context snapshots', 'Freeze selected text so you can identify exactly what was supplied.', [
    section('why', 'A snapshot is intentionally immutable', ['A context snapshot captures selected documents, approved knowledge, and additional text after a preview. Later source edits do not rewrite the captured content. This is useful when a review or conversation depends on knowing what information was available at the time, rather than only seeing today’s version of a document.']),
    section('capture', 'Capture and reuse context', [], { steps: ['Open Library and choose Context snapshots.', 'Capture context with a name and optional project scope.', 'Choose sources or start from a context pack.', 'Preview the assembled text and remove irrelevant material.', 'Save the reviewed snapshot; copy, export, or attach it as a chat note when needed.'] }),
    section('stale', 'Handle changed sources', ['The snapshot viewer can flag sources that changed, disappeared, or were archived. Capture a new snapshot for updated context rather than expecting an old one to mutate. Attaching a snapshot as a note does not run an agent. A provider receives context only when you explicitly send a message that includes it.']),
  ], { related: ['chat-context', 'documents', 'knowledge-decisions'], appLink: { view: 'library', label: 'Open Library' } }),

  article('outputs', 'knowledge', 'Versioned outputs', 'Keep deliverables linked to the work and conversation that produced them.', [
    section('record', 'Store something that can be reviewed', ['An output holds Markdown or text plus its type, reviewer name, and optional Route, project, and producing session. Use it for a deliverable rather than leaving the final answer buried in a chat. Provenance links make it easier to inspect the original brief and understand how the result was produced.']),
    section('versions', 'Changes create a new review target', ['Saving a new version preserves the previous version and asks for a short explanation of what changed. Compare with the previous version to focus review. Approval applies only to one exact version; it does not carry forward automatically after editing. Export the selected version when you need a Markdown copy.']),
    section('limits', 'Content is not verification', ['Pasting a result into Library does not independently verify its claims. Include enough source information and acceptance criteria for the reviewer to check. Dedicated evidence attachments, specialized code/image review, and controlled external sharing are not yet part of this output system.'], { note: 'An approved output does not merge Git changes, authorize tools, or mark the linked Route Done.' }),
  ], { related: ['output-review', 'route-agreements', 'message-actions'], appLink: { view: 'library', label: 'Open outputs' } }),

  article('output-review', 'knowledge', 'Review, comments, and revisions', 'Make a decision about one version and preserve the reason.', [
    section('inspect', 'Review the actual deliverable', ['Open an output, choose the version, and read its content alongside the linked acceptance checklist. Comments can quote a passage from that version, making feedback specific. Resolve or reopen comments as the discussion progresses; resolving a comment alone does not approve the output.']),
    section('decision', 'Approve or request changes', [], { steps: ['Confirm you are reviewing the current intended version.', 'Check the brief, evidence, and acceptance criteria.', 'Record your reviewer name and feedback.', 'Approve this version or request changes explicitly.', 'For requested changes, inspect the linked revision Route created with the feedback.'] }),
    section('meaning', 'Know what the decision does', ['Requested changes create a revision Route but do not launch an agent. Approval leaves the original Route status unchanged. A newer output version needs a fresh decision. Reviewer names are recorded attribution, not authenticated signatures; public identity verification and multi-user authorization are separate, unimplemented service capabilities.']),
  ], { related: ['outputs', 'route-agreements', 'service-boundaries'] }),

  article('provider-connections', 'integrations', 'AI connections and execution', 'Inspect account access before authorizing a provider or starting work.', [
    section('api-keys', 'Connect with an API key', [`API-key connections are implemented for ${API_PROVIDERS.map(item => item.name).join(', ')}. Open a provider detail page and choose Add API key. Keys are encrypted on the server for your account and workspace; they are never returned to the browser or stored in agent profiles. Saving a key makes no provider request and does not enable live execution.`, 'Choose Test a model, load the catalog or configure model IDs, and explicitly send the short test request. A successful reply enables the connection. Tests and later conversations may spend your provider API credits. Model catalogs and manually configured IDs do not certify every model. Fireworks, Perplexity, Qwen and Z.ai need model IDs entered from their catalogs. Qwen also needs the region and Model Studio workspace ID from its endpoint.', 'OpenRouter and Hugging Face offer both browser authorization and API credentials. One method is active per provider, person and workspace. Choosing a new key or completing browser authorization replaces the active method. A new key always needs a fresh model test. Hugging Face personal tokens need permission to call Inference Providers; they do not require Frondose’s OAuth app. Disconnect removes Frondose’s stored credential; revoke it at the provider if needed.']),
    section('separation', 'Profiles and connections are different', ['AI connections opens a compact provider catalog. Select a provider to read its account route, usage limits, and current capabilities before choosing Connect or Manage. Codex and Claude Code are existing local runners: they need a signed-in CLI on the machine running Frondose and do not create public hosted subscription access. Creating an agent does not install a runner, authenticate an account, or guarantee that the current provider setup is compatible.']),
    section('browser-execution', 'Use a reviewed browser-account request', ['OpenRouter and configured Hugging Face profiles can execute reviewed conversations and scheduled agent prompts with an explicit model and the current user’s workspace authorization. Load a provider model catalog deliberately; execution itself makes no hidden account or model-list probe. The exact compiled prompt is sent in one bounded, non-streaming completion request. A final reply may propose supported workspace actions, but each action still needs human review and current permissions.', 'These browser providers have no native MCP or project-file tools, automatic retries for uncertain delivery, or integrated API usage ledger. Missing usage is unknown rather than zero. Mocked transport and schedule checks do not verify live-account OAuth, paid inference, or every available model.']),
    section('setup', 'Follow the provider-specific route', [], { steps: ['Open AI connections and select the intended provider.', 'Choose API key, browser authorization where offered, or Manage runner for Codex/Claude Code. Codex also offers an opt-in stdio session bridge.', 'Save your API key and any model/region settings. Hugging Face browser sign-in needs the operator’s OAuth app. Copilot offers Connect with GitHub through a registered app and per-user server SDK. Each user needs Copilot access; a plain GitHub account alone is insufficient. Local installations also retain a separate device-sign-in ACP alternative.', 'For an API key or Copilot, explicitly test one model to finish connecting. A saved key, GitHub authorization or ACP handshake alone is not inference verification.', 'Return to Frondose or an agent profile, select the provider and model, then review context before sending. Copilot supports General chat and pending Frondose action proposals; native/file tools are disabled.'] }),
    section('failures', 'Keep failures honest', ['Authentication, configuration, or provider network failures remain real failures. Frondose does not silently switch to simulation. A connected status is not a guarantee that every later request succeeds; account access and provider behavior can change. Do not paste tokens into chats or documents, and do not use a retry to work around an unresolved permission problem.']),
  ], { related: ['agent-profiles', 'session-progress', 'chat-access'], appLink: { view: 'connections', label: 'Open connections' } }),

  article('github-drive', 'integrations', 'GitHub and Google Drive context', 'Hosted connection plans; authorization and sync are currently paused.', [
    section('current-release', 'Not usable in this release', ['These hosted GitHub and Google Drive connection plans are separate from AI connections and from the independent local desktop integration catalog. New hosted authorization, resource reads, synchronization, imports, and provider writes are paused. Existing records are preserved, not proof of active access. The sections below describe the future design, not steps you can complete today.']),
    section('github', 'GitHub references and repositories', ['The GitHub connection discovers repositories after authorization. Select repositories in Resources, then use Code to browse branches, folders, source files, and comparisons. Sync reads issues, pull requests, or commits into linked source records. Import relevant records as Frondose Routes, projects, or documents. A repository link, a Team Resource branch link, and a linked working folder remain different things: reading online code does not create a checkout or run shell commands.']),
    section('drive', 'Drive metadata and linked content', ['Google Drive connects through provider authorization after the Frondose operator configures the OAuth application. Select files and folders before synchronizing their references. Link mode preserves source identity; cache mode stores the content returned by the particular adapter. Docs, Sheets, and Slides have separate connection entries for their supported reading and writing operations. A Drive selection does not automatically grant every agent access: enable agent access, choose its allowed agents, and review their delegated permissions.']),
    section('boundaries', 'Check connection scope', [], { bullets: ['Connect only the account and resources you intend to use.', 'Read the readiness and setup state before relying on a resource.', 'Disconnect deliberately if access should no longer be used.', 'Verify external links and current contents before citing them.', 'Treat service logos as identity, not proof of connection or capability.'] }),
  ], { related: ['connection-github', 'connection-google-drive', 'connection-sync'], appLink: { view: 'connections', label: 'Manage connections' } }),

  article('integration-roadmap', 'integrations', 'AI connections and service integrations', 'Read current connection states accurately.', [
    section('detail-page', 'Read an AI connection detail page', ['Open AI connections and choose a provider from the table. Its detail page explains routes, usage, actions and limits before authorization. OpenRouter offers browser authorization; Hugging Face OAuth needs operator setup. GitHub Copilot offers registered GitHub App/OAuth App authorization and a private per-user SDK runtime; local ACP remains a separate alternative. Public mode disables shared machine CLI accounts and host Workbench operations. It requires HTTPS, stable encrypted storage, a provisioned owner and invitations; actual hosting and live account verification remain operator tasks. Codex and Claude Code use their existing machine account manager only on local installations; public users can use OpenAI/Anthropic API connections instead. Codex can opt into the app-server session bridge. Opening any detail page never starts a run or spends credits.', 'The standalone extension placeholder has been removed. Frondose desktop offers separate, provider-specific Settings → Integrations pages for supported local access. Do not treat an older Connected label in the hosted product as proof that an operation is available.']),
    section('states', 'Read the connection state', ['Codex and Claude are the current local AI runners. Hosted service-integration authorization, synchronization, and actions are paused, even if an older record says Connected. Existing records are preserved. A local runner connection is not public hosted AI access, and listed model IDs are not a guarantee that a provider account can run them.']),
    section('use', 'Do not assume planned actions run', ['Ask Frondose for supported workspace actions and review its proposals before applying them. A listed integration does not make all actions executable. OpenRouter and configured Hugging Face can power reviewed conversations and scheduled agent prompts through the current user’s workspace authorization and an explicit model. Their final replies may propose supported local workspace actions, but API providers have no native or project-file tools. Account checks and short model tests are separate operations, not action approval or real-account certification. API usage is not yet part of the CLI metering ledger.']),
    section('request', 'Describe the workflow you need', ['Useful feedback explains the source, desired action, data involved, and who should approve it. “Bring this selected document into a reviewed context snapshot” is more actionable than “Integrate everything.” Frondose’s Feedback form is currently a preview: submitting it does not transmit a request to a support service.']),
  ], { related: ['provider-connections', 'github-drive', 'service-boundaries'] }),

  article('preferences', 'settings', 'Preferences and appearance', 'Make Frondose readable and familiar without changing the underlying work.', [
    section('empty-colors', 'Global, team, and individual tab colors', ['Open Settings → Appearance & navigation → Icons & name colors. Global empty-state illustration color affects artwork only and defaults to neutral theme text color. Area tints apply only when Use Area illustration colors is explicitly enabled. Empty-state text defaults to neutral theme colors, independently of Area tint; use Empty-state text color for an explicit custom heading and description color. Action buttons retain their own colors. Global tab icon color separately applies to navigation symbols. Global tab name color starts at Theme default (neutral); choose Match each tab icon or a custom color to change it. Custom hex values use #RRGGBB and Apply. Keep text readable in both light and dark mode; arbitrary colors do not guarantee accessible contrast. These preferences are personal to this browser.', 'Ordinary tab icons and names navigate together without opening color popups. In Appearance settings, find an individual tab to edit its icon and name color without changing its shape. Follow team settings inherits the current team policy; Follow global bypasses the team. Custom color overrides both. Name colors can independently inherit, match the icon, stay neutral, or use custom color. Individual tabs are also searchable in Appearance settings. These overrides belong to this browser and workspace and are not exported.', 'Custom sidebar groups also appear in the color settings. Their icon and name defaults flow into contained tabs automatically unless a tab has an explicit override. Click a custom group name to adjust its colors. Moving a tab out of the group removes that inherited group color. Group count badges appear only when the group is collapsed.']),
    section('chat-follow', 'Follow a long conversation without losing your place', ['Preferences includes Smoothly follow new chat messages, enabled by default. Opening a chat positions you at the latest message. As content arrives while you are at the bottom, a short easing motion keeps the newest content visible. The animation also responds to messages that become taller when their content loads.', 'Scroll upward to read older messages and following pauses. New messages do not pull you back down. Select Latest messages, or scroll back to the bottom, to resume. Disabling the preference keeps following behavior but makes it immediate. Frondose’s Reduce motion setting and your operating system’s reduced-motion preference also skip the animation. Ordinary trackpad and wheel scrolling stay native; Frondose does not replace them with simulated momentum. This preference is personal to this browser.']),
    section('personal', 'Start with the interface you use daily', ['Settings groups personal preferences separately from Route, project, agent, and administration configuration. Use Preferences and Appearance & navigation to tune the interface. Search settings by the task you want to perform; operational content such as documents and saved views also has a dedicated page outside Settings.']),
    section('theme', 'Theme and motion', ['Light and dark appearance use shared tokens for surfaces, text, controls, and focus. The sidebar remains visually distinct from the main canvas. Reduced-motion preferences minimize travel and morph feedback. Keyboard navigation stays immediate, so decorative pointer animation never delays an action.']),
    section('scroll-fades', 'Read scrolling surfaces', ['Scrollable lists, panels, dialogs, and horizontal tab rows fade subtly at edges where more content is hidden. The fade clears at the start or end and when the content fits. Keyboard focus and high-contrast forced-colors mode keep controls fully visible. The effect follows the current theme and does not block clicking or scrolling.']),
    section('profile', 'Keep your profile recognizable', ['Your profile has a unique username, a shared Display name, a private Display name (You), and an optional picture. The private name is visible only to you; an empty private name uses your shared name. Usernames are optional for existing accounts, unique on this installation, and do not change your login or permissions. PNG, JPEG, and WebP pictures can be uploaded or dropped into the picture control, then cropped, zoomed, and repositioned. The saved image is a bounded thumbnail that fills the entire circular profile frame. A profile name is presentation and attribution; it does not establish an authenticated public identity.'], { note: 'Do not infer a live public service from the presence of Billing, Security, or API settings. Those pages explain their current boundaries.' }),
  ], { related: ['sidebar-customization', 'keyboard-shortcuts', 'service-boundaries'], appLink: { view: 'settings', id: 'appearance', label: 'Open appearance settings' }, image: 'settings' }),

  article('sidebar-customization', 'settings', 'Customize your sidebar', 'Keep navigation focused without losing access to hidden work.', [
    section('open', 'Choose what deserves a shortcut', ['Sidebar customization is available through Appearance & navigation and the help menu. It controls section visibility and arrangement, and restores individually hidden items. To hide an individual project, Area, agent, or chat, use that item’s sidebar options. Hiding changes presentation; it does not archive or delete content or change what data it can access. Pinning a tab places it in the header or floating dock, not a second sidebar group.']),
    section('workflow', 'Hide and restore deliberately', [], { steps: ['Open an individual item’s sidebar options to hide its shortcut.', 'Open Sidebar customization to review section visibility and arrangement.', 'Restore individually hidden items there when you need them again.', 'Use Search and commands to reach a hidden page without restoring its shortcut.', 'Keep the sidebar focused on the destinations you actually revisit.'] }),
    section('scope', 'A personal arrangement', ['Sidebar preferences, header shortcuts, dock position, and starred objects are personal to this browser and workspace. They are not shared team policy and do not enforce permission boundaries. Drag the main or Settings sidebar border to change its width; drag all the way left to collapse it, then hover on the edge to reveal it temporarily. The full-screen sidebar with a draggable mini-page is not implemented. Saved views remain a single navigation tab; their creation and management happen inside the page.']),
  ], { related: ['navigation', 'saved-views', 'preferences'], appLink: { view: 'settings', id: 'appearance', label: 'Customize navigation' } }),

  article('keyboard-shortcuts', 'settings', 'Keyboard shortcuts', 'Move quickly without letting shortcuts launch work unexpectedly.', [
    section('essentials', 'Everyday controls', [], { bullets: ['Command/Ctrl K opens Search and commands.', 'Command/Ctrl [ and Command/Ctrl ] move through workspace-local navigation history.', '[ folds or expands the app sidebar when you are not typing.', 'F favorites the current supported item.', 'Shift B opens sidebar customization.', '? opens the keyboard shortcuts reference.', 'Escape closes a dialog or cancels an incomplete shortcut.'] }),
    section('create', 'Create and navigate with short sequences', ['The shortcut reference lists G sequences for destinations and N sequences for creating objects. For example, N then P opens project creation, N then R opens Route creation, and N then C opens chat creation. These sequences open authored forms; they do not approve action requests or launch agents.']),
    section('typing', 'Typing takes priority', ['Letter-key shortcuts can be disabled and do not intercept typing or composition in editors and inputs. A short sequence expires if you pause too long. If a shortcut appears not to work, check whether a dialog or text field currently owns focus, then consult the reference instead of repeatedly pressing keys.']),
  ], { related: ['navigation', 'sidebar-customization', 'preferences'] }),

  article('import-export', 'settings', 'Export, import, and backup limits', 'Move workspace content without accidentally restoring execution authority.', [
    section('export', 'Know what the archive contains', ['Workspace JSON exports cover supported workspace records, workflow content, message bookmarks and reactions, and project pictures. An export is not a complete backup of every runtime artifact. Team Resource uploads, agent memory/action tables, full change-log history, chat follow-up drafts, and some branch relationships are not all included. Download important resource files separately and preserve appropriate database backups.']),
    section('import', 'Import into a new workspace', ['Import validates and remaps references transactionally and creates a new workspace. It never restores folder grants, credentials, active runs, terminal permissions, or automatic execution. Outputs require fresh review, approved knowledge becomes draft, and plans and repeat schedules are paused or reset as needed.']),
    section('check', 'Review the result before use', [], { steps: ['Keep the original export unchanged until verification finishes.', 'Import into the new workspace.', 'Check important projects, Routes, documents, and references.', 'Review imported outputs and knowledge again.', 'Relink only the folders and connections you deliberately want to authorize.'], note: 'Imported message text is content, not trusted current agent instructions. Static frontend files alone are not a workspace backup.' }),
  ], { related: ['team-resources', 'agent-memory', 'service-boundaries'], appLink: { view: 'settings', id: 'storage', label: 'Open import & export' } }),

  article('service-boundaries', 'settings', 'Current service boundaries', 'Separate implemented workspace features from future public infrastructure.', [
    section('current', 'What the current app provides', ['Frondose pairs its interface with a trusted-host server runtime for persistence, provider processes, project files, and terminals. It now includes account setup, password sign-in, revocable sessions, invitation links, ranked membership, scoped permission grants, approval decisions, and an audit trail. The connection platform adds encrypted OAuth credentials, selected resources, native imports, conflict review, and synchronization jobs. These implemented services do not automatically deploy or operate a public Frondose installation.']),
    section('not-live', 'What requires operator setup', ['Real provider authorization requires registering the Frondose application with that provider and securely configuring server credentials. Webhook delivery needs a reachable endpoint and matching signing secret. Invitation links can be created and accepted, but invitation emails and password-recovery emails are not configured. MFA, billing, public third-party OAuth grants, managed hosting, and spend enforcement remain separate work. A legacy team directory entry or a reviewer display name is not an authenticated account.']),
    section('public', 'Before any public deployment', ['Public availability still requires production hosting, TLS, database backups, secret management, email delivery, recovery procedures, and execution isolation. Workbench processes run on the host machine; enabling password sign-in does not turn that host into a sandbox for untrusted users. Validate the supported deployment boundaries before exposing the service. The Docs and Feedback interfaces also do not create a support operation: Feedback submission remains an explicit placeholder.']),
  ], { related: ['developer-architecture', 'developer-api', 'import-export'], appLink: { view: 'settings', id: 'security', label: 'Open security settings' } }),

  article('developer-architecture', 'developers', 'Architecture and runtime', 'Understand the frontend, service, storage, and execution layers.', [
    section('layers', 'A frontend and a trusted-host service', ['The React interface lives in src and uses Vite for development and production builds. The server layer owns persistence, validation, provider integration, workflow services, and Workbench operations. The app is not a static page with simulated terminal responses: real execution requires the server runtime and its dependencies.']),
    section('services', 'Keep service boundaries explicit', ['Dedicated services handle coordination, workflow review, team resources, agent awareness, chat collaboration, imports, and Workbench. Database persistence is backed by the schema in server/schema.sql. UI constraints improve usability, but scope checks, stale-state validation, and approval enforcement belong in the server rather than only in component state.']),
    section('packaging', 'Static packaging does not replace runtime', ['The build preserves Sites packaging alongside the frontend. A static deployment can serve the interface, but it does not supply the database, provider processes, or real PTYs. Preserve the existing hosting handoff files when contributing, and make any public service architecture a deliberate separate decision.'], { note: 'Do not publish the current internal API as a public endpoint without authentication, authorization, and execution-isolation work.' }),
  ], { related: ['developer-api', 'developer-testing', 'workbench-safety'] }),

  article('developer-api', 'developers', 'Internal APIs and action contracts', 'Work with validated service boundaries, not a promised public developer API.', [
    section('internal', 'The API serves the app runtime', ['The current API is an internal application boundary used by the frontend and trusted-host services. There is no supported public API-key or webhook platform merely because API & webhooks appears in Settings. Endpoint shapes and storage details should be treated as implementation details, not a stable third-party contract.']),
    section('validation', 'Preserve server-side checks', ['Mutations validate identifiers, workspace scope, parent relationships, allowed fields, and concurrency where applicable. Reviewed agent actions additionally check their decision state and current target values. A client should display errors honestly instead of overwriting newer state or inventing a successful local result after a rejected mutation.']),
    section('agents', 'Proposals and native tools', ['Agent awareness uses bounded reviewed context. The final-reply proposal protocol remains available; native tools are a separate, explicit per-run opt-in through a private run-bound MCP bridge. The server validates scope, current authority and replay protection. Workspace writes create pending requests, not self-approved changes. If adding a new action, design its target scope, exact review display, stale-state behavior, audit outcome, and replay protection together.']),
  ], { related: ['developer-architecture', 'agent-actions', 'service-boundaries'] }),

  article('developer-testing', 'developers', 'Testing and safe contributions', 'Verify behavior without contacting real providers or altering a real workspace.', [
    section('checks', 'Use the existing verification layers', ['The npm test suite exercises persistence, validation, scope, replay protection, review gates, context safety, imports, navigation, timeline, and Workbench behavior. npm run build verifies the production client and preserved packaging. Browser scripts under scripts cover product flows, settings, workflow review, and Workbench with isolated fixtures.']),
    section('fixtures', 'Keep execution disposable', ['UI scripts create temporary API databases and caches. Provider adapters are tested with injected implementations rather than real Codex or Claude accounts. Workbench tests use disposable repositories and processes. A passing injected-provider test confirms application behavior; it does not verify the owner’s live account or current external-provider compatibility.']),
    section('contribute', 'Check the boundary you changed', [], { steps: ['Read AGENTS.md and preserve unrelated working-tree changes.', 'Add focused validation or behavior tests for the change.', 'Run the relevant suite and the production build.', 'Inspect rendered behavior in light, dark, and narrow layouts when UI changes.', 'Record remaining implementation limits instead of presenting a roadmap entry as complete.'] }),
  ], { related: ['developer-architecture', 'developer-api', 'session-progress'] }),

  article('notifications', 'settings', 'Inbox and notification preferences', 'Choose useful in-app updates without hiding required decisions.', [
    section('inbox', 'Use the inbox for recorded updates', ['Settings → Notifications controls completed-session and failed-session updates in Frondose’s inbox. These updates help distinguish work that finished from work that needs investigation. The inbox has read state, while Home has its own attention and check-in behavior; clearing one is not a statement that the underlying work was accepted.']),
    section('configure', 'Tune session updates', [], { steps: ['Open Notifications in Settings.', 'Choose whether completed sessions should appear in the inbox.', 'Choose whether failed sessions should appear.', 'Open a relevant update to inspect the session outcome.'] }),
    section('approvals', 'Required approvals remain visible', ['Permission requests stay visible until resolved. Turning off a notification category cannot approve a request or remove a required review. Likewise, snoozing an item on Home temporarily changes attention presentation, not the approval screen.']),
    section('delivery', 'External delivery is separate', ['Slack, email, and push delivery are not configured in this release. A notification preference does not send external messages or create a background reminder. Use the integration catalog to understand which delivery workflows are planned.']),
  ], { related: ['home-focus', 'session-progress', 'agent-actions'], appLink: { view: 'settings', id: 'notifications', label: 'Open notifications' } }),

  article('personal-instructions', 'settings', 'Personal agent instructions', 'State communication preferences that apply to future live sessions.', [
    section('purpose', 'Describe how you want to work', ['Agent personalization holds your personal communication instructions. They are included in future live sessions alongside the selected agent’s own instructions. Use them for durable preferences such as explaining tradeoffs, distinguishing verified facts from assumptions, or asking before changing the requested direction.']),
    section('write', 'Write instructions that travel well', [], { steps: ['Open Settings → Agent personalization.', 'Describe a small set of stable communication preferences.', 'Avoid task-specific details that belong in the current brief.', 'Save the instructions and review them when your workflow changes.'] }),
    section('separation', 'Keep task facts with the task', ['A current project deadline or a one-off source should be in the Route or conversation context, not a global personalization field. Personal instructions can otherwise make unrelated work carry outdated assumptions. Use the agent profile for that collaborator’s purpose and approved project-scoped memory for durable project information.']),
    section('limits', 'Instructions do not grant authority', ['Personalization never grants tools or permissions. It does not bypass read-only mode, change a provider’s account access, or allow the model to approve its own Frondose actions. Review execution and action requests separately.']),
  ], { related: ['agent-profiles', 'agent-memory', 'tool-permissions'], appLink: { view: 'settings', id: 'personalization', label: 'Edit personal instructions' } }),

  article('profile-pictures', 'settings', 'Profile and project pictures', 'Upload, crop, and position a picture that remains clear at small sizes.', [
    section('formats', 'Choose a supported source', ['Profile and project picture controls accept PNG, JPEG, and WebP images by file selection or drag and drop. A source image is not used blindly as the final thumbnail: Frondose opens its crop and reposition dialog so you can choose the framing before saving.']),
    section('crop', 'Frame the important part', [], { steps: ['Open the profile or project picture control.', 'Choose or drop a supported image.', 'Adjust the square crop, zoom, and position.', 'Check that the important subject remains recognizable at thumbnail size.', 'Save the crop, then check the result where the picture is displayed.'] }),
    section('choice', 'Prefer readable images', ['A clear face, symbol, or simple project mark works better than a screenshot full of small text. Leave some space around the subject to avoid a cramped result. The original source file is preserved; the saved app picture is a bounded 512px thumbnail.']),
    section('identity', 'A picture is presentation', ['The profile name and image help identify the displayed author and account area. They are not public identity verification, membership approval, or a substitute for the future authentication service.']),
  ], { related: ['preferences', 'projects', 'account-security'], appLink: { view: 'settings', id: 'profile', label: 'Edit profile' } }),

  article('daily-preferences', 'settings', 'Home, send keys, and date pickers', 'Set small defaults that change everyday interaction.', [
    section('home', 'Choose where an ordinary visit starts', ['Default home determines which page opens when Frondose has no explicit deep link. Choices include Home, Focus, Inbox, Projects, Routes, Chats, and Agents. A link to a particular object should still take you to that object; the preference is a starting destination, not a redirect for every navigation.']),
    section('send', 'Choose a send key deliberately', ['You can send chat messages with Enter or with Command/Ctrl Enter. Shift Enter always adds a new line. If you often write several paragraphs, the modifier-key option can reduce accidental sends. It does not change the recipient or access mode, so those still need to be checked in the composer.']),
    section('week', 'Match your calendar convention', ['First day of the week changes Frondose’s date pickers between Monday and Sunday. It is a calendar presentation preference, not a change to existing deadlines or the meaning of stored dates.']),
    section('apply', 'Make one change at a time', ['After changing a default, try the related interaction once. That is more useful than changing many settings and later guessing which one altered your workflow. Theme, density, and motion live separately in Appearance & navigation.']),
  ], { related: ['preferences', 'chat-basics', 'home-focus'], appLink: { view: 'settings', id: 'preferences', label: 'Open preferences' } }),

  article('tool-permissions', 'settings', 'Tool permissions and concurrency', 'Set enforced execution limits independently of agent instructions.', [
    section('editing', 'Control project editing', ['Tools & permissions offers a per-session choice or a Read only default for project editing. Read only prevents live runs from enabling project edits; General chat remains restricted separately. A request in an agent’s instructions cannot override the server’s execution policy.']),
    section('concurrency', 'Bound simultaneous live work', ['The simultaneous-session setting limits the number of live runs accepted by the current Frondose instance. The runner checks the limit again before a live launch. Choose a level that you can supervise and that the host and provider can support; a higher number is not a promise of higher throughput.']),
    section('separate', 'Keep three boundaries separate', [], { bullets: ['Provider connection: which runner and account are available.', 'Session permissions: what the selected execution mode may do.', 'Frondose action approval: whether a specific proposed workspace mutation is accepted.'] }),
    section('connections', 'Connections are not automatic agent tools', ['An external service appearing as connected does not automatically expose it to every agent. Review the implemented connection behavior and the exact context being sent. These settings do not make Workbench terminals sandboxed.']),
  ], { related: ['chat-access', 'agent-actions', 'terminals'], appLink: { view: 'settings', id: 'permissions', label: 'Configure tool permissions' } }),

  article('agent-collections', 'chats-agents', 'Organize agents into collections', 'Group collaborators by purpose without inventing automatic orchestration.', [
    section('purpose', 'Use a collection as a useful roster', ['Collections group selected agent profiles around a purpose, such as research, implementation, or review. An agent can remain a distinct collaborator with its own instructions and provider while being part of a reusable group. The collection’s description should explain when that group is useful.']),
    section('create', 'Create a collection', [], { steps: ['Open Settings → Collections.', 'Add a collection with a descriptive name and purpose.', 'Select the relevant agent profiles.', 'Save it and review the membership as responsibilities change.'] }),
    section('scope', 'Membership is not an assignment', ['Adding an agent to a collection does not dispatch work, contact its provider, or put it into every chat. Assign the right profile to the actual Route, plan step, or message when work is ready. Avoid names that imply a guaranteed autonomous team if the workflow still needs explicit preparation and review.']),
    section('maintain', 'Keep the roster usable', ['A smaller set of clearly differentiated profiles is easier to choose from than many nearly identical agents. Update profile instructions when their purpose changes; changing the collection description alone does not rewrite each member’s instructions.']),
  ], { related: ['agent-profiles', 'coordination', 'instruction-presets'], appLink: { view: 'settings', id: 'collections', label: 'Manage collections' } }),

  article('instruction-presets', 'chats-agents', 'Reusable instruction presets', 'Reuse a reviewed starting point while keeping profile changes deliberate.', [
    section('purpose', 'Store the repeatable instructions', ['Instructions & presets keeps named instruction content with a description of when to use it. It is useful for a standard review method, a research format, or an implementation checklist that should not be rewritten from memory for each profile. Keep task-specific source material outside the preset.']),
    section('apply', 'Apply with the target profile in mind', [], { steps: ['Create or edit a preset in Settings.', 'Explain its purpose and write the actual instructions.', 'Review the text for assumptions that may not fit every project.', 'Deliberately apply it to the intended agent profile.', 'Inspect that profile before its next live session.'] }),
    section('version', 'Do not assume invisible inheritance', ['Presets provide versioned instruction resources, but complete inherited workspace, team, and project layers are not implemented. A preset edit should not be interpreted as proof that every agent now uses the new text. Review effective profile instructions where correctness matters.']),
    section('safety', 'Keep permissions out of prose', ['A preset can ask an agent to explain intended actions, but it cannot grant tool access or bypass approval. Use the corresponding server-enforced controls for execution boundaries.']),
  ], { related: ['agent-profiles', 'personal-instructions', 'tool-permissions'], appLink: { view: 'settings', id: 'presets', label: 'Manage instruction presets' } }),

  article('context-packs', 'knowledge', 'Reusable context packs', 'Collect sources for a recurring question without silently sending them.', [
    section('pack', 'A recipe for context', ['A context pack groups selected documents, memory notes, and additional text with a purpose. Think of it as a reusable source selection, not an autonomous agent memory or a continuously synchronized knowledge base. It helps prepare similar briefs while keeping source choice visible.']),
    section('build', 'Build a focused pack', [], { steps: ['Open Settings → Context & memory.', 'Name the pack after the situation it supports.', 'Choose the necessary documents and memory notes.', 'Add a short explanation or missing context.', 'Review the assembled material before using it in a brief or snapshot.'] }),
    section('snapshot', 'Freeze text when reproducibility matters', ['Library can start context capture from a pack. Preview and save a snapshot to record the exact text rather than relying only on references to sources that may change. A changed source should lead to a new review when the context will inform consequential work.']),
    section('budget', 'Prefer relevance over volume', ['Remove obsolete or competing instructions and keep credentials out. Large packs can crowd out the current request and encounter context limits. Creating a pack or selecting it never sends anything to an AI on its own.']),
  ], { related: ['chat-context', 'context-snapshots', 'knowledge-decisions'], appLink: { view: 'settings', id: 'context', label: 'Manage context packs' } }),

  article('execution-queue', 'projects-routes', 'Queue work briefs', 'Prepare the next task without starting it before you are ready.', [
    section('queue', 'Separate prioritization from execution', ['The execution queue stores ordered work briefs with optional project and agent references. Its states describe preparation: Ready, On hold, or Prepared. A brief in the queue is not a running session, and ordering it does not create a background dispatcher.']),
    section('prepare', 'Prepare a reviewable brief', [], { steps: ['Create a work brief with the intended outcome and relevant context.', 'Choose at most one project and one agent for the entry.', 'Use On hold when a prerequisite or decision is missing.', 'Open a session for review when the work is ready.', 'Check the actual prompt, provider, folder, and permissions before launch.'] }),
    section('maintain', 'Keep prepared work current', ['A queued brief can become stale while a project changes. Recheck sources and dependencies when preparing it rather than treating its place in the queue as approval. If several independent outcomes are mixed together, split them into separate Routes or plan steps with clearer acceptance conditions.']),
    section('result', 'Connect the result afterwards', ['Record the resulting session and useful output where the work is tracked. A prepared state does not independently confirm completion, acceptance, or successful integration.']),
  ], { related: ['coordination', 'routes', 'session-progress'], appLink: { view: 'settings', id: 'queue', label: 'Open execution queue' } }),

  article('handoffs', 'projects-routes', 'Write an effective handoff', 'Transfer outcome, context, and next steps together.', [
    section('purpose', 'Make the next step understandable', ['A handoff records a summary and next steps with related projects, receiving agents, and a Draft, Ready, or Accepted state. It is useful when work changes direction or responsibility. A transcript alone rarely tells the next collaborator which conclusions were accepted and which questions remain open.']),
    section('content', 'Include the necessary information', [], { bullets: ['The intended outcome and the work already completed.', 'The exact output or source that should be reviewed.', 'Known limitations and failed attempts that matter.', 'Remaining decisions, blockers, and the next concrete action.', 'The context the receiver should inspect before executing.'] }),
    section('review', 'Review the handoff state', ['Use Draft while the summary is incomplete. Ready means it is prepared for someone to inspect, not that an agent has started. Accepted records the handoff decision; it does not independently verify all claims in the text.']),
    section('launch', 'Keep launch separate', ['Selecting a receiving agent does not contact that provider. Prepare the next session deliberately, review its actual context and permissions, and link useful results back to the project or Route.']),
  ], { related: ['coordination', 'execution-queue', 'outputs'], appLink: { view: 'settings', id: 'handoffs', label: 'Open handoffs' } }),

  article('requests-intake', 'projects-routes', 'Capture and triage requests', 'Turn incoming needs into clear work rather than immediate execution.', [
    section('capture', 'Record the need before choosing a solution', ['A request stores the desired outcome, requester attribution, and a triage state. Use it for incoming feedback or an idea that still needs interpretation. Keep the original need visible instead of immediately translating it into an agent command whose scope may be wrong.']),
    section('triage', 'Choose the next decision', [], { steps: ['Capture what is requested and who raised it.', 'Use New for unreviewed needs or Considering while questions remain.', 'Clarify the expected outcome and constraints.', 'Accept a worthwhile request or decline it with a useful explanation.', 'Turn an accepted request into a linked Route and complete its brief.'] }),
    section('assignment', 'Assign when the work is understood', ['Assignment & intake links request capture, Route templates, and supervised routing rules. A template can supply a starting brief and suggested assignees, but the resulting work still needs review before execution.']),
    section('limits', 'A request inbox is not external support', ['This workflow records workspace requests. It does not mean that Slack, email, or the Feedback placeholder automatically delivers customer messages here. Requester names are attribution, not verified account identity.']),
  ], { related: ['routes', 'templates-recurrence', 'integration-roadmap'], appLink: { view: 'settings', id: 'requests', label: 'Open requests' } }),

  article('goals', 'projects-routes', 'Goals and outcome progress', 'Connect desired outcomes to projects without mistaking a count for proof.', [
    section('goal', 'Describe the change you want', ['A goal links an outcome and success criteria to projects, with an owner recorded for clarity. Use it when multiple projects contribute to a broader result. A goal should explain why that work matters rather than repeating a project’s task list with a bigger title.']),
    section('create', 'Set up a meaningful goal', [], { steps: ['Write the desired outcome and the evidence that would demonstrate it.', 'Record the owner responsible for reviewing progress.', 'Link only projects that genuinely contribute.', 'Review their Routes and accepted outputs as work develops.'] }),
    section('progress', 'Read the progress indicator correctly', ['Goal progress is calculated from active leaf Routes in linked projects. A leaf has no children; parent Routes are not counted again alongside their children, even when those children are archived. Done leaves count as completed, while cancelled and archived leaves are excluded and shown separately. Missing, restricted, or invalid hierarchy context prevents a trustworthy complete percentage.', 'This is a measure of recorded workflow completion, not independent verification that a business or user outcome occurred. It is not weighted by effort or importance: a project with many small leaves can influence the count differently from one with a few large deliverables. Completing a child does not automatically complete its parent, a milestone, or the goal. Review the success criteria and accepted outputs separately.']),
    section('review', 'Use evidence alongside the count', ['Keep measured results or observations in documents and outputs. Revisit the goal’s success criteria when scope changes, and distinguish “we completed the planned work” from “the intended outcome happened.”']),
  ], { related: ['projects', 'milestones-timeline', 'outputs'], appLink: { view: 'settings', id: 'goals', label: 'Open goals' } }),

  article('project-updates', 'projects-routes', 'Project updates', 'Leave a concise record of progress, risks, and the next decision.', [
    section('purpose', 'Explain the project at a useful checkpoint', ['A project update records what changed, why it matters, and what comes next. Use one after a milestone, a material scope change, a new risk, or a review. It belongs to a single project and remains attached to that project’s access scope. It is different from the system activity below the feed, which records events such as a Route edit or session outcome.', 'Updates can explicitly change the current project status or reported progress when published. Dates, lead, health and milestone criteria retain their own controls. Reported progress is a manual assessment, not calculated Route completion. A useful update points readers to the actual evidence instead of replacing it with a reassuring headline.']),
    section('write', 'Draft a clear project update', [], { steps: ['Open the project and select its Updates tab.', 'In Updates & replies, add an optional title that describes the change, not just the date.', 'Choose a type such as Progress, Decision, Risk, Blocker, Release, or Outcome.', 'Add an optional health signal and explain the reason in the body.', 'Write the completed work, evidence, outstanding risks, and next decision. Link to relevant documents or provider evidence that readers are permitted to open.', 'Save draft to continue privately, or publish when the text is ready for people with access to the project.'] }),
    section('example', 'Separate evidence from the next promise', ['For example, a title might be “Repository import passes scoped fixture checks.” The body can say which repositories or fixtures were checked, what was actually verified, what remains untested, and who must make the next decision. If OAuth registration or live consent is still missing, say so rather than calling the connection finished.', 'A concise structure is Completed, Evidence, Risks, and Next. These are writing prompts, not required database fields. Include a concrete ask when progress depends on a decision: identify the option, owner, and consequence. Avoid copying every command or repeating an entire chat; readers should be able to distinguish the current result from planned work.']),
    section('health', 'Use a health signal with an explanation', ['Choose On track when the current plan remains credible, At risk when a threat could affect it, or Blocked when a missing decision or dependency prevents meaningful progress. No health signal leaves this update without a colored assessment. The label belongs to this saved update; it does not automatically change project health or the status of its Routes.', 'Explain changes in health using observable facts. “At risk because provider review is pending and the release date depends on it” is more useful than “Things are getting complicated.” Revisit the project’s actual target date and milestone scope separately if the assessment changes the plan.']),
    section('drafts', 'Keep preparation private until publication', ['Saved top-level drafts are server-persisted and author-only within Frondose’s normal target-access checks. Open your own drafts from Updates to continue writing. Publication requires content and records when the update became shared. Replies publish directly; they do not have the same private-draft workflow.', 'After publishing, the entry cannot be turned back into a private draft. Correct it with Edit if you are its author and still have project write access, or archive it when appropriate. Keep credentials and sensitive information out of drafts as well as published posts: draft privacy is not encryption against the operator of the host.']),
    section('read', 'Read the project in context or across the workspace', ['The project Updates tab keeps updates beside its current work. Updates at #/updates provides a combined view of accessible published top-level updates and a separate view of your drafts. Narrow that feed by object type, update type, health, or text when you need to compare changes across projects.', 'Use the entry link to return to a particular update and the target link to inspect the project. Links do not grant permissions. If an entry is unavailable, check the current workspace, target access, archive state, and active filters before creating another copy. A workspace-wide feed is not a public changelog.']),
    section('discussion', 'Discuss, correct, and recover', ['Reply to keep questions attached to the update they concern. Reactions acknowledge an entry but do not approve an output or authorize work. An @agent mention records text for review and never starts that agent; use the normal chat and execution flow for an actual response.', 'Published edit history preserves saved corrections without exposing private draft text. The original author can edit with current project write access; authorized moderators can archive or restore published entries when their permissions allow it, not rewrite another person’s update. Archive is recoverable and hides the entry from active feeds. Restore its archived parent first when resuming a reply thread.', 'If a save reports a version conflict, reopen the latest entry and compare changes. Do not overwrite from an old form or repeatedly publish another copy after an uncertain response. Verify the saved result before retrying.']),
    section('delivery', 'Know what publication does not do', ['Publishing an update does not send Slack or email notifications, publish a website release, call a provider, complete Routes, approve outputs, or start agents. Those actions remain explicit and separate. A Release update documents a release; it does not deploy one.', 'Private drafts are excluded from workspace exports. Published updates and replies are restored as historical records into a new workspace, with their target and thread IDs remapped. Imported author names do not restore account access or author editing privileges, and reactions are not restored. Preserve durable requirements and decisions in the project brief or reviewed documents as well as in progress updates.']),
  ], { related: ['updates-replies', 'projects', 'milestones-timeline', 'notifications'], appLink: { view: 'updates', label: 'Open Updates' }, image: 'projects' }),

  article('team-settings', 'workspace', 'Area settings and workspace defaults', 'Prepare a domain of work without silently granting agent access.', [
    section('identity', 'Choose identity and inherited colors', ['Open Area settings to edit the name, description, line icon and colors. Unicode emojis and uploaded My Emojis are not Area identity icons. Area color supplies inherited navigation-icon and empty-state image tints; the identity icon can have an independent tint. Unset colors follow the corresponding global preference.', 'Tab names retain neutral/global defaults unless deliberately changed. Individual tab overrides take priority. Empty-state headings and descriptions remain neutral independently of the image tint, unless you choose a separate text color; action buttons retain normal styles. Area identity persists with workspace content; personal tab/global preferences stay in this browser.']),
    section('quick-icon', 'Change the icon where you work', ['Click the Area identity icon to open its icon-only picker. Choose a color before selecting a line icon; selection saves immediately. Escape or Close leaves the previous choice unchanged. Ordinary navigation-tab icons navigate rather than opening this picker.']),
    section('general', 'Save focused instructions and defaults', ['Area settings can store instructions, selected workspace agents, Context Packs and known read-tool preferences. These are preparation defaults only: saving them does not launch an agent, inject text into current runs, connect a provider or grant access. Review-only is the current permission policy; instructions cannot override it.']),
    section('defaults', 'Understand what still comes from the workspace', ['Labels, statuses, templates and other existing workspace configuration retain their current scope. Links to their settings do not create Area-specific copies. Exact Context Inspector and workflow execution will be implemented in later slices; current Area defaults are not a substitute for reviewing context and permissions before a run.']),
    section('people', 'Keep Contacts optional', ['Enable Contacts when a directory is useful. Existing names, contact details and role descriptions are preserved when the section is hidden. Directory entries are not authenticated users, invitations or access grants. You can use an Area entirely on your own.']),
    section('lifecycle', 'Preserve work through reorganization', ['Former Team IDs, linked resources, grants and history remain intact. Archiving an Area retains its linked work. Exports preserve Area settings; imports remap their selected references into a new workspace and retain review-only policy, never restoring credentials or folder access.']),
  ], { related: ['teams', 'team-resources', 'labels-statuses', 'context-snapshots'], appLink: { view: 'settings', id: 'teams', label: 'Open Area settings' } }),

  article('emoji-library', 'settings', 'Named emojis and reaction icons', 'Understand the difference between workspace symbols and the chat picker.', [
    section('library', 'Upload your own emojis', ['Open Settings → Emojis → New emoji. Name your emoji, choose or drop one PNG, JPEG/JPG, or WebP image (up to 10 MB), adjust the square crop, and save. Frondose stores a bounded raster thumbnail in this workspace. SVG, remote image URLs, and animated uploads are not supported. Existing Unicode entries remain readable.']),
    section('picker', 'Use My Emojis', ['Choose My Emojis in the reaction picker to react with a saved workspace image. In a chat composer, choose Insert emoji, then My Emojis, or type the named :shortcode: copied from Settings. The shortcode renders as the image in saved messages; code blocks keep literal text. Renaming an emoji keeps its original shortcode, so past messages remain readable. Archived emojis disappear from new selections but remain visible in history and can be restored in Settings. Their shortcodes stay reserved. My Emojis is workspace-scoped, not a private account library. Icons still support custom colors; images and native emojis keep their own colors.']),
    section('meaning', 'Do not make color carry everything', ['Give named symbols a clear explanation. A green icon may be visually useful, but text or context should still make the intended meaning understandable without relying on color vision. Keep a reaction lightweight; a review requiring an accountable decision belongs in the output review flow.']),
    section('boundary', 'Reactions are not approval controls', ['A checkmark reaction does not approve a tool request, accept an output version, or complete a Route. Use the dedicated action when the state change matters.']),
  ], { related: ['message-actions', 'output-review', 'agent-actions'], appLink: { view: 'settings', id: 'emojis', label: 'Open emoji library' } }),

  article('archive-retention', 'settings', 'Archive, restore, and retention', 'Remove clutter without confusing hiding with deletion.', [
    section('three-actions', 'Choose the action you actually need', ['Hiding removes a shortcut from your personal sidebar. Archiving removes an object from active work while keeping recoverable history. Permanent deletion removes data where a specific confirmed deletion flow is provided. These are different actions; a cleaner sidebar is not evidence that old data has been removed.']),
    section('restore', 'Find archived work', ['Data & retention provides archived content and workspace-resource restoration controls. Some operational pages, such as Library, also expose an Archived filter. Check the object’s own archive view if it disappears from an active list before creating a replacement.']),
    section('policy', 'No automatic expiration', ['The current policy retains content until it is explicitly removed. There is no automatic deletion policy enabled. A review date on knowledge or a project target date does not schedule the content for deletion.']),
    section('backup', 'Export before significant cleanup', ['Review export coverage and preserve resources that the JSON archive does not contain. Team Resource files can be downloaded individually. Restoring an archived object should not be used as a substitute for a tested backup and recovery plan.']),
  ], { related: ['import-export', 'sidebar-customization', 'team-resources'], appLink: { view: 'settings', id: 'retention', label: 'Open data & retention' } }),

  article('audit-history', 'settings', 'Change history and audit log', 'Inspect recorded edits without claiming a tamper-proof access record.', [
    section('record', 'See what changed', ['The Audit log lists recent recorded workspace content changes with an item name, action, object type, and timestamp. Filtering helps narrow the list, and Inspect displays the recorded before and after values. This can explain why a document or configuration resource no longer matches what you remember.']),
    section('inspect', 'Investigate a specific edit', [], { steps: ['Open Settings → Audit log.', 'Filter by an item name or action.', 'Inspect the relevant record.', 'Compare the before and after values with the current item.', 'Export the log separately when you need a reference copy.'] }),
    section('history', 'History has a starting point', ['Document and agent directories provide item-history views, and Library knowledge has revision restoration into a draft. Records only exist for changes captured by the implemented logging. Older history is not reconstructed merely because a History button exists.']),
    section('limits', 'Use the record appropriately', ['This is edit history, not a tamper-proof security or access log. It does not establish authenticated attribution, record every filesystem action, or replace external compliance evidence. The full history also has export and retention limits.']),
  ], { related: ['knowledge-decisions', 'import-export', 'account-security'], appLink: { view: 'settings', id: 'audit', label: 'Inspect audit log' } }),

  article('usage-limits', 'settings', 'Usage and limits', 'Read recorded activity separately from provider billing.', [
    section('activity', 'Measure the runs Frondose recorded', ['Usage & limits shows session counts for the last 7 or 30 days, including completed and failed or interrupted work. The chart groups sessions by day. The mode filter can show live sessions only or include simulations; keep that distinction visible when evaluating your actual execution activity.']),
    section('meaning', 'Counts are not cost', ['Session counts do not say how many tokens a provider billed or how much the work cost. Different tasks can consume very different amounts of provider capacity. Frondose does not reconcile provider charges in this release and does not present unknown cost as zero.']),
    section('limits', 'Use the available limit correctly', ['The concurrent-session setting is enforced by the current runner instance. It limits simultaneous live execution, not total monthly spend. Provider rate limits and account allowances are separate constraints.']),
    section('budget', 'Check the provider for billing', ['Use the provider’s own usage information for authoritative account charges. Frondose budget enforcement is not active because reliable metering and a billing policy are not yet implemented. A small session count is not a guarantee of a small bill.']),
  ], { related: ['tool-permissions', 'billing', 'session-progress'], appLink: { view: 'settings', id: 'usage', label: 'Open usage & limits' } }),

  article('billing', 'settings', 'Billing and provider subscriptions', 'Understand which service owns the charge.', [
    section('separate', 'Frondose and an AI provider are different services', ['A provider connection uses the account and runtime configured for that provider. Its usage is governed by the provider’s account terms and billing, not by an assumed Frondose plan. Creating a profile or recording an output does not establish that provider execution is free or included.']),
    section('current', 'No Frondose payment flow is configured', ['The Billing page explains the current boundary: this development build does not have paid plans, payment-method collection, or invoice generation. Those require a merchant setup, pricing, and a billing integration. Frondose does not ask you to enter card details into a placeholder form.']),
    section('cost', 'Unknown means unknown', ['Usage & limits records activity, but token costs and provider charges are unavailable rather than zero. Check the provider’s billing page when you need an authoritative charge or remaining allowance.']),
    section('planning', 'Budget outside the current app', ['Until metering and enforcement exist, supervise live launches and use the provider’s own controls where available. Frondose’s concurrency limit is a workload limit; it cannot be used as a spending cap or a billing guarantee.']),
  ], { related: ['usage-limits', 'provider-connections', 'service-boundaries'], appLink: { view: 'settings', id: 'billing', label: 'Open billing information' } }),

  article('applications-webhooks', 'developers', 'Applications, API keys, and webhooks', 'Distinguish inbound grants from connections Frondose uses.', [
    section('direction', 'Two directions of integration', ['Connections describe services Frondose connects to, such as an execution provider or repository source. Applications describes third-party software authorized to access Frondose itself. These are not interchangeable: connecting GitHub does not issue a GitHub application unrestricted access to this workspace.']),
    section('grants', 'Connection OAuth and public application grants differ', ['Frondose can now hold encrypted provider OAuth credentials and enforce connection permissions for its own members and delegated agents. It still does not issue third-party applications general Frondose OAuth grants or public API keys. A provider account being connected does not authorize an unrelated application to access the workspace. Use People & permissions to inspect human access and the connection’s Agents tab to enable specific agent delegates.']),
    section('webhooks', 'Incoming provider events and background jobs', ['Supported connection adapters can accept verified incoming provider events after the operator configures a public endpoint and signing secret. The connection Sync page exposes provider-event enablement, scheduled reconciliation, update policy, job status, and retries. Events queue work through the connection’s resource selection and permissions. Periodic checks cover gaps between events. This inbound mechanism is different from a general outbound webhook service for arbitrary customer URLs; the latter is not implemented.']),
    section('internal', 'Treat the runtime API as an application contract', ['The application endpoints now use the configured account session and workspace permissions. They remain a runtime contract rather than a versioned public developer API with third-party credentials and support guarantees. Provider adapters, imports, approval requests, and background jobs all use the same permission boundaries. A public integration surface would additionally need its own registration, consent, scoped grants, quotas, compatibility policy, and revocation flows.']),
  ], { related: ['developer-api', 'service-boundaries', 'integration-roadmap'], appLink: { view: 'settings', id: 'api', label: 'Open API & webhooks information' } }),

  article('account-security', 'settings', 'Local privacy and security', 'Protect the workspace on your computer.', [
    section('access', 'Open Frondose without an account', ['Frondose opens the local workspace directly. The local profile is for display and attribution, not a sign-in. Older sign-ins, sessions and invitations no longer grant access.']),
    section('device', 'Keep your computer protected', ['Use your operating system’s screen lock and disk encryption. Keep backups of the local data directory and do not expose the loopback server to your network.']),
    section('providers', 'Review provider access separately', ['Optional AI and repository providers may require their own sign-in. Review connections and their permissions separately from local access.']),
    section('restore', 'Protect shared computers and backups', ['Anyone with access to the running desktop session can open your workspace. Keep backups private and do not put the raw data directory in a public or shared folder. Use Settings → Privacy to review data controls, and go to Integrations to disconnect providers you no longer use.']),
  ], { related: ['service-boundaries', 'provider-connections'], appLink: { view: 'settings', id: 'privacy', label: 'Open Privacy settings' } }),

  article('help-feedback', 'getting-started', 'Docs, feedback, and help', 'Find practical guidance and understand the current feedback preview.', [
    section('menu', 'Use the question-mark menu', ['The help menu brings together Docs, Contact us, a concise tool glossary, Sidebar customization, Keyboard shortcuts, product updates, and Settings. The profile control is in the top header rather than a duplicate sidebar footer. Contact us is explicitly a non-delivering placeholder; Download App is not offered as an installer.']),
    section('docs', 'Find the right kind of guidance', ['Docs groups articles by workflow, from getting started and project work through agents, settings, and developer boundaries. Use search for a feature name or a symptom. Article sections and related guides help you move from a quick answer to the surrounding workflow without reading the whole catalog.']),
    section('feedback', 'Preview a message', ['Help → Contact us lets you write a description and choose or drop up to five files, 10 MB each. For a bug, include what you expected, what happened, and the shortest sequence that reproduces it. Avoid passwords, tokens, and unnecessary personal information in screenshots.']),
    section('placeholder', 'Nothing is sent or saved', ['Preview message does not transmit the text or upload attachments. The draft exists only while the dialog stays open; closing clears it. This is an explicit placeholder, not a delivered support report. Keep your own copy if you need to preserve the information.']),
  ], { related: ['navigation', 'keyboard-shortcuts', 'troubleshoot-missing'] }),

  article('workspace-management', 'workspace', 'Manage workspace identity', 'Keep separate areas of work distinct and recognizable.', [
    section('identity', 'Name the workspace for its purpose', ['Workspace settings lets you edit the name and description and inspect its stable identifier. A clear description explains what belongs here and what should go into a different workspace. The displayed workspace address is an identifier; public hosting is not configured merely because it has a slug.']),
    section('separation', 'Create another workspace when the context changes', ['A new workspace provides a separate area for projects, teams, agent profiles, and configuration resources. Use it when the work genuinely needs a different context, rather than creating separate workspaces just to hide a few sidebar items. Personal navigation controls are better for that.']),
    section('switch', 'Recheck context after switching', ['Workspace-local navigation history resets when switching. Verify the current workspace before creating work or applying a proposed change, especially when project or agent names are similar. An agent memory scoped to one workspace is not a universal memory for every workspace.']),
    section('moving', 'Use import for content transfer', ['Workspace import creates new identifiers and does not restore folder authority, connections, or live execution. Review imported content before using it. It is not a merge or a way to overwrite a current workspace silently.']),
  ], { related: ['workspace-basics', 'import-export', 'agent-memory'], appLink: { view: 'settings', id: 'workspace', label: 'Open workspace settings' } }),

  article('troubleshoot-provider', 'chats-agents', 'When an agent cannot reply', 'Check setup, request state, and access before retrying.', [
    section('state', 'First determine what failed', ['A failed reply can come from runner configuration, account access, a rejected provider request, an interrupted process, or an empty final response. Open the short error’s expandable diagnostics to identify the category. Do not assume every failure means that the user message itself was invalid.']),
    section('checks', 'Work through the relevant checks', [], { steps: ['Check Connections for the selected provider’s readiness.', 'Confirm that the intended agent and access mode were selected.', 'For project work, verify that the correct working folder is linked.', 'Inspect whether a previous request is still running or has uncertain delivery.', 'Resolve the reported setup or provider problem before retrying.'] }),
    section('auth', 'Authorization errors require authorization fixes', ['A 403 or other access rejection is not repaired by changing the UI or repeatedly resending the same prompt. Review the provider’s actual account and setup state. Never paste authentication tokens into a chat as a workaround.']),
    section('evidence', 'Keep diagnostics useful but private', ['When sharing a failure report, include the useful error category and reproduction steps, not an unreviewed dump that may contain private paths or account information. Injected-provider tests do not guarantee live account compatibility.']),
  ], { related: ['provider-connections', 'session-progress', 'chat-access'], appLink: { view: 'connections', label: 'Check connections' } }),

  article('troubleshoot-missing', 'workspace', 'When an item seems to be missing', 'Check presentation, scope, and filters before recreating work.', [
    section('scope', 'Check where you are looking', ['An object may be outside the current workspace, project scope, or active filter. Similar names across projects can make this easy to miss. Start by checking the workspace switcher and the page’s project or state filters, then search for a distinctive part of the title.']),
    section('navigation', 'Hidden is not deleted', ['Sidebar hiding removes a shortcut but keeps the underlying content. Use Search and commands or sidebar customization to find it again. Saved views has a dedicated page, so an individual query need not appear as a nested sidebar item to exist.']),
    section('archive', 'Inspect lifecycle state', ['Archived items may be excluded from active lists. Check Data & retention or the relevant page’s Archived filter. A saved view can also become empty because the matching Routes changed stage or their parent project was archived. Review its criteria instead of assuming the view lost its data.']),
    section('context', 'Different contexts have different contents', ['A context snapshot deliberately preserves its old text, while a document can have newer content. Agent overview lists are bounded and do not contain every object. Missing from an agent’s summary is not proof that an item was deleted from the workspace.']),
  ], { related: ['search', 'archive-retention', 'saved-views', 'context-snapshots'] }),

  article('developer-interface', 'developers', 'Interface conventions', 'Extend Frondose without breaking its accessibility or product language.', [
    section('components', 'Use the existing authored controls', ['Frondose uses shared authored dialogs, fields, menus, tooltips, and icon components. Reuse these before introducing another interaction pattern. A dialog should preserve keyboard navigation, restore opener focus, and prevent interaction with its background. Native file-selection and provider authorization windows are intentional platform boundaries.']),
    section('visuals', 'Respect shared tokens and meaning', ['Use theme tokens for both light and dark surfaces. Search focus surrounds the complete field container, including its icon. Interface glyphs use the shared Lucide/Morphicons wrapper; complex empty-state artwork is a separate catalog, not an enlarged navigation icon. Service identities use the shared real-logo registry with appropriate fallbacks.']),
    section('motion', 'Motion should never block the action', ['Pointer feedback can emphasize an icon’s meaning, but keyboard activation stays immediate. Honor both app and OS reduced-motion preferences and cancel animations when the relevant interface disappears. Do not animate every icon in a dense picker or loop empty-state illustrations.']),
    section('truth', 'Design the unavailable state honestly', ['A planned service needs a clear explanation, not a successful-looking fake result. A feedback preview must not claim delivery. When adding a feature, update documentation to describe what actually persists, executes, and requires approval.']),
  ], { related: ['developer-testing', 'developer-architecture', 'preferences'] }),
];

export const DOC_ARTICLES = [...WORKSTATION_DOCS, WORKSTATION_RELEASE, ...DOC_NOVEMBER, ...DOC_LOCAL, ...REFERENCE_ARTICLES, ...DOC_WORKFLOWS, ...DOC_GOVERNANCE, ...DOC_CONNECTIONS, ...DOC_COLLABORATION, ...DOC_TEMPLATES_AND_SCHEDULING, ...DOC_AI_CONNECTIONS];
